 -- Helpers are private. Only the three thin entry points are executable by API.
  CREATE FUNCTION public.fn_izo_teren_autorizat(p_proiect bigint,p_lock boolean) RETURNS bigint
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_uid uuid:=public.fn_izo_uid(); v_emp bigint; v_owner boolean;
BEGIN
 IF p_lock THEN
  SELECT employee_id,is_owner INTO v_emp,v_owner FROM public.profiles WHERE id=v_uid FOR SHARE;
 ELSE SELECT employee_id,is_owner INTO v_emp,v_owner FROM public.profiles WHERE id=v_uid; END IF;
 IF v_emp IS NULL THEN RETURN NULL; END IF;
 IF v_owner THEN RETURN v_emp; END IF;
 IF p_lock THEN
  PERFORM 1 FROM public.user_module_access WHERE profile_id=v_uid AND module='executie.izometrie'
   AND access_level IN ('editor','admin') ORDER BY id FOR SHARE;
 ELSE
  PERFORM 1 FROM public.user_module_access WHERE profile_id=v_uid AND module='executie.izometrie' AND access_level IN ('editor','admin');
 END IF;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF p_lock THEN
  PERFORM 1 FROM public.izo_atribuiri WHERE profile_id=v_uid AND proiect_id=p_proiect AND activ
   AND rol='inginer_izometrie' AND current_date BETWEEN valabil_de AND coalesce(valabil_pana,current_date) ORDER BY id FOR SHARE;
 ELSE
  PERFORM 1 FROM public.izo_atribuiri WHERE profile_id=v_uid AND proiect_id=p_proiect AND activ
   AND rol='inginer_izometrie' AND current_date BETWEEN valabil_de AND coalesce(valabil_pana,current_date);
 END IF;
 IF NOT FOUND THEN RETURN NULL; END IF;
 RETURN v_emp;
END $f$;

  CREATE FUNCTION public.fn_izo_teren_entra(p_proiect bigint,p_functie text) RETURNS text
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_n integer; v_lipsa text[];
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ COMMITTED' USING ERRCODE='25001'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
 IF session_user<>'authenticator' OR public.fn_izo_jwt_rol() IS DISTINCT FROM 'authenticated' OR public.fn_izo_uid() IS NULL THEN RETURN 'fara_drept'; END IF;
 IF coalesce(current_setting('izo.montaj_ctx',true),'')<>'' OR coalesce(current_setting('izo.receptie_ctx',true),'')<>''
  OR coalesce(current_setting('izo.registru_tx',true),'')<>'' THEN RETURN 'fara_drept'; END IF;
 IF public.fn_izo_teren_autorizat(p_proiect,false) IS NULL THEN RETURN 'fara_drept'; END IF;
 INSERT INTO public.izo_rata_apeluri(profile_id,functie,fereastra_de_la,n) VALUES(public.fn_izo_uid(),p_functie,date_trunc('minute',clock_timestamp()),1)
 ON CONFLICT(profile_id,functie) DO UPDATE SET
 n=CASE WHEN izo_rata_apeluri.fereastra_de_la=excluded.fereastra_de_la THEN izo_rata_apeluri.n+1 ELSE 1 END,
 fereastra_de_la=excluded.fereastra_de_la RETURNING n INTO v_n;
 IF v_n>30 THEN RETURN 'limita'; END IF;
 v_lipsa:=public.fn_izo_porti_lipsa();
 IF cardinality(v_lipsa)>0 THEN RAISE EXCEPTION 'E4b porti: %',v_lipsa; END IF;
 RETURN NULL;
END $f$;

  CREATE FUNCTION public.fn_izo_pv_lipsa(p_radacini bigint[]) RETURNS bigint[]
 LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 SELECT coalesce(array_agg(b.id ORDER BY b.id),'{}'::bigint[]) FROM public.magazie_bucati b
 WHERE b.id=ANY(p_radacini) AND b.aviz_intrare_id IS NOT NULL AND NOT EXISTS
 (SELECT 1 FROM public.izo_documente_intrare d WHERE d.id=b.aviz_intrare_id AND d.eveniment_pv_id IS NOT NULL)
$f$;

  CREATE FUNCTION public.fn_izo_teren_snapshot(p_proiect bigint,p_tronson bigint) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_doc jsonb;
BEGIN
 IF NOT public.fn_izo_citire(p_proiect) OR NOT EXISTS(SELECT 1 FROM public.executie_tronsoane WHERE id=p_tronson AND proiect_id=p_proiect) THEN
  RETURN jsonb_build_object('cod','fara_drept'); END IF;
 -- One statement / one MVCC snapshot, including all mutable rows (never max(id)).
 WITH frunze AS (
  SELECT b.id,b.uid,b.serie,b.serie_canon,b.sarja,b.lungime_mm,b.lungime_cm,b.perete_mm,b.tip_cod,b.stare,b.tronson_id,b.depozit_id,b.server_ver,
   EXISTS(SELECT 1 FROM public.izo_rezervari r WHERE r.bucata_id=b.id AND r.activa AND (r.expira_dupa IS NULL OR r.expira_dupa>now())) rezervata,
   (SELECT r.tronson_id FROM public.izo_rezervari r WHERE r.bucata_id=b.id AND r.activa AND (r.expira_dupa IS NULL OR r.expira_dupa>now())) rezervata_tronson,
   cardinality(public.fn_izo_pv_lipsa(ARRAY[coalesce(b.radacina_id,b.id)]))>0 fara_pv
  FROM public.magazie_bucati b WHERE b.proiect_id=p_proiect AND b.tip_cod IS NOT NULL AND b.stare NOT IN ('taiata','anulata')
   AND NOT EXISTS(SELECT 1 FROM public.magazie_bucati c WHERE c.parinte_id=b.id AND c.stare<>'anulata')
 ), proprii AS (
  SELECT d.*, (d.identificare IS DISTINCT FROM 'nerezolvata' AND d.tip<>'cuplare' AND NOT EXISTS
   (SELECT 1 FROM public.izo_rezervari r WHERE r.declaratie_id=d.id AND r.activa AND (r.expira_dupa IS NULL OR r.expira_dupa>now()))) rezervare_pierduta
  FROM public.izo_declaratii d WHERE d.proiect_id=p_proiect AND d.tronson_id=p_tronson AND d.declarat_de=public.fn_izo_uid()
   AND d.stare NOT IN ('aprobata','respinsa','stearsa')
 )
 SELECT jsonb_build_object('proiect_id',p_proiect,'tronson_id',p_tronson,
 'frunze',coalesce((SELECT jsonb_agg(to_jsonb(f)||jsonb_build_object('disponibila',NOT rezervata AND NOT fara_pv AND
  (stare='pe_tronson' AND tronson_id=p_tronson OR stare IN ('sosit','receptionat','retur') AND depozit_id IS NOT NULL)) ORDER BY f.id) FROM frunze f),'[]'::jsonb),
 'suduri',coalesce((SELECT jsonb_agg(to_jsonb(s)||jsonb_build_object('capete',(SELECT jsonb_agg(to_jsonb(c) ORDER BY c.id) FROM public.izo_suduri_capete c WHERE c.sudura_id=s.id AND c.activ)) ORDER BY s.id) FROM public.izo_suduri s WHERE s.proiect_id=p_proiect AND s.tronson_id=p_tronson),'[]'::jsonb),'numar_urmator',(SELECT CASE WHEN cfg.sens_numerotare='descrescator' THEN nullif(greatest(coalesce((SELECT min(w.nr)-1 FROM public.izo_suduri w WHERE w.tronson_id=p_tronson AND w.stare<>'anulata'),cfg.nr_sudura_start),0),0) ELSE coalesce((SELECT max(w.nr)+1 FROM public.izo_suduri w WHERE w.tronson_id=p_tronson AND w.stare<>'anulata'),1) END FROM public.izo_tronson_config cfg WHERE cfg.tronson_id=p_tronson),
 'config',(SELECT to_jsonb(c) FROM public.izo_tronson_config c WHERE tronson_id=p_tronson),
 'praguri',(SELECT to_jsonb(c)-ARRAY['modificat_de','modificat_la'] FROM public.izo_proiect_config c WHERE proiect_id=p_proiect),
 'declaratii',coalesce((SELECT jsonb_agg(to_jsonb(d) ORDER BY d.id) FROM proprii d),'[]'::jsonb),
 'bucati_declarate',coalesce((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.uid) FROM public.izo_bucati_declarate c JOIN proprii d ON d.id=c.declaratie_id),'[]'::jsonb),
 'lanturi',coalesce((SELECT jsonb_agg(to_jsonb(f) ORDER BY f.id) FROM frunze f WHERE stare='montata' AND tronson_id=p_tronson),'[]'::jsonb),
 'tombstone',coalesce((SELECT jsonb_agg(jsonb_build_object('id',b.id,'uid',b.uid,'stare',b.stare,'server_ver',b.server_ver) ORDER BY b.id)
  FROM public.magazie_bucati b WHERE b.proiect_id=p_proiect AND b.tip_cod IS NOT NULL AND b.stare IN ('taiata','anulata')),'[]'::jsonb),
 'server_ver_max',greatest(coalesce((SELECT max(server_ver) FROM public.magazie_bucati WHERE proiect_id=p_proiect),0),
 coalesce((SELECT max(server_ver) FROM public.izo_declaratii WHERE proiect_id=p_proiect),0),
 coalesce((SELECT max(server_ver) FROM public.izo_rezervari WHERE proiect_id=p_proiect),0),
 coalesce((SELECT max(server_ver) FROM public.izo_suduri WHERE proiect_id=p_proiect),0),
 coalesce((SELECT max(c.server_ver) FROM public.izo_suduri_capete c JOIN public.izo_suduri w ON w.id=c.sudura_id WHERE w.proiect_id=p_proiect),0),
 coalesce((SELECT server_ver FROM public.izo_tronson_config WHERE tronson_id=p_tronson),0))) INTO v_doc;
 RETURN jsonb_build_object('snapshot_id',gen_random_uuid(),'checksum',encode(sha256(convert_to(v_doc::text,'UTF8')),'hex')) || v_doc;
END $f$;

  CREATE FUNCTION public.fn_izo_teren_intern(p_proiect bigint,p_tronson bigint,p_dispozitiv uuid,p_pregateste boolean) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_cod text; v_f public.izo_fronturi; v_owner uuid;
BEGIN
 v_cod:=public.fn_izo_teren_entra(p_proiect,CASE WHEN p_pregateste THEN 'pregateste' ELSE 'instantaneu' END);
 IF v_cod IS NOT NULL THEN RETURN jsonb_build_object('cod',v_cod); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.executie_tronsoane WHERE id=p_tronson AND proiect_id=p_proiect) THEN RETURN jsonb_build_object('cod','fara_drept'); END IF;
 IF p_pregateste THEN
  BEGIN
  IF p_dispozitiv IS NULL THEN RETURN jsonb_build_object('cod','eroare'); END IF;
  -- Tronson-scoped front arbitration. No project advisory (activation order §10.5).
  INSERT INTO public.izo_dispozitive(dispozitiv_id,profile_id) VALUES(p_dispozitiv,public.fn_izo_uid()) ON CONFLICT DO NOTHING;
  SELECT profile_id INTO v_owner FROM public.izo_dispozitive WHERE dispozitiv_id=p_dispozitiv;
  IF v_owner IS DISTINCT FROM public.fn_izo_uid() THEN RAISE EXCEPTION 'fara_drept' USING ERRCODE='IZ004'; END IF;
  INSERT INTO public.izo_fronturi(proiect_id,tronson_id,profile_id,dispozitiv_id,expira_la)
   VALUES(p_proiect,p_tronson,public.fn_izo_uid(),p_dispozitiv,now()+interval '12 hours') ON CONFLICT DO NOTHING;
  SELECT * INTO v_f FROM public.izo_fronturi WHERE tronson_id=p_tronson AND activ FOR UPDATE;
  IF v_f.profile_id<>public.fn_izo_uid() OR v_f.dispozitiv_id<>p_dispozitiv THEN RAISE EXCEPTION 'alt_dispozitiv' USING ERRCODE='IZ004'; END IF;
  IF public.fn_izo_teren_autorizat(p_proiect,true) IS NULL THEN RAISE EXCEPTION 'fara_drept' USING ERRCODE='IZ004'; END IF;
  PERFORM 1 FROM public.izo_tronson_config WHERE tronson_id=p_tronson FOR SHARE;
  IF NOT EXISTS(SELECT 1 FROM public.izo_tronson_config WHERE tronson_id=p_tronson AND flux_montaj)
   OR coalesce(public.fn_izo_nivel(p_proiect),'off') NOT IN ('stoc','montaj') THEN RAISE EXCEPTION 'flux_inactiv'; END IF;
  PERFORM 1 FROM public.magazie_bucati WHERE proiect_id=p_proiect AND id=radacina_id ORDER BY id FOR UPDATE;
  UPDATE public.izo_fronturi SET expira_la=now()+interval '12 hours',server_ver=nextval('public.izo_server_ver_seq') WHERE id=v_f.id;
   UPDATE public.izo_rezervari SET expira_dupa=now()+interval '36 hours',server_ver=nextval('public.izo_server_ver_seq')
   WHERE autor_profile_id=public.fn_izo_uid() AND tronson_id=p_tronson AND activa AND expira_dupa IS NOT NULL;
  EXCEPTION WHEN SQLSTATE 'IZ004' THEN RETURN jsonb_build_object('cod',SQLERRM); END;
 ELSE
  IF public.fn_izo_teren_autorizat(p_proiect,true) IS NULL THEN RETURN jsonb_build_object('cod','fara_drept'); END IF;
 END IF;
 RETURN public.fn_izo_teren_snapshot(p_proiect,p_tronson);
END $f$;

  CREATE FUNCTION public.fn_izo_teren_instantaneu(p_proiect bigint,p_tronson bigint) RETURNS jsonb
 LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 SELECT public.fn_izo_teren_intern(p_proiect,p_tronson,NULL,false)
$f$;

  CREATE FUNCTION public.fn_izo_teren_payload(p_payload jsonb) RETURNS jsonb
 LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path = public, pg_temp AS $f$
DECLARE v_p jsonb:=p_payload-'gps'; v_key text; v_allowed text[];
BEGIN
 IF jsonb_typeof(v_p) IS DISTINCT FROM 'object' OR v_p-ARRAY['proiect_id','tronson_id','uid','preverificare_uid','versiune_baza','tip',
 'zi','bucata','sursa','baza_mm','puncte_mm','copii','confirmare','capat_amonte','amonte','sudura','capat1','capat2','lungime_montata_mm',
 'depinde_de_uid','depinde_de_versiune','serie_bruta','sarja_declarata','perete_declarat','lungime_masurata_mm',
 'ultimele3_reconfirmate','km_propus_m','executant','poanson','data_montaj','randuri']<>'{}'::jsonb THEN
  RAISE EXCEPTION 'payload' USING ERRCODE='IZ001'; END IF;
 IF jsonb_path_exists(v_p,'$.**.gps') OR jsonb_path_exists(v_p,'$.**.lat') OR jsonb_path_exists(v_p,'$.**.lon') THEN
  RAISE EXCEPTION 'gps_nested' USING ERRCODE='IZ001'; END IF;
 FOREACH v_key IN ARRAY ARRAY['bucata','sursa','confirmare','amonte','sudura','capat1','capat2'] LOOP
  IF v_p ? v_key THEN
   v_allowed:=CASE v_key WHEN 'bucata' THEN ARRAY['bucata_id','decl_uid'] WHEN 'sursa' THEN ARRAY['bucata_id','decl_uid']
    WHEN 'capat1' THEN ARRAY['bucata_id','decl_uid','capat'] WHEN 'capat2' THEN ARRAY['bucata_id','decl_uid','capat']
     WHEN 'confirmare' THEN ARRAY['mod','cm','la','masurata_mm'] WHEN 'amonte' THEN ARRAY['tip','bucata_id','decl_uid','capat']
    ELSE ARRAY['nr','sufix'] END;
   IF jsonb_typeof(v_p->v_key)<>'object' OR (v_p->v_key)-v_allowed<>'{}'::jsonb THEN RAISE EXCEPTION 'payload_nested' USING ERRCODE='IZ001'; END IF;
  END IF;
 END LOOP;
 IF v_p ? 'copii' AND EXISTS(SELECT 1 FROM jsonb_array_elements(v_p->'copii') c WHERE
  jsonb_typeof(c)<>'object' OR c-ARRAY['uid','lungime_mm','destinatie','depozit_destinatie_id','calculata']<>'{}'::jsonb) THEN
  RAISE EXCEPTION 'copii_payload' USING ERRCODE='IZ001'; END IF;
 IF v_p ? 'randuri' AND EXISTS(SELECT 1 FROM jsonb_array_elements(v_p->'randuri') c WHERE
  jsonb_typeof(c)<>'object' OR c-ARRAY['uid','versiune']<>'{}'::jsonb) THEN RAISE EXCEPTION 'randuri_payload' USING ERRCODE='IZ001'; END IF;
 RETURN v_p;
END $f$;

  CREATE FUNCTION public.fn_izo_teren_op(p_dispozitiv uuid,p_op jsonb,p_payload jsonb,p_emp bigint,p_hash text,p_front public.izo_fronturi) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_s public.izo_preverificari; v_d public.izo_declaratii; v_b public.magazie_bucati;
 v_c public.izo_bucati_declarate; v_cfg public.izo_proiect_config;
 v_uid uuid:=public.fn_izo_uid(); v_type text:=p_op->>'tip_op'; v_id uuid:=(p_op->>'op_id')::uuid;
 v_p jsonb:=p_payload; v_ref jsonb; v_child jsonb; v_source bigint; v_decl uuid; v_root bigint;
 v_len integer; v_base integer; v_sum integer; v_n integer; v_i integer; v_letter integer; v_points integer[];
 v_code text; v_left text; v_right text; v_prev text; v_state text:='ciorna'; v_ident text;
 v_conflict text; v_date date; v_json jsonb; v_response jsonb; v_gps jsonb; v_affected bigint;
BEGIN
 IF (p_op->>'versiune_format')::integer IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'versiune_format' USING ERRCODE='IZ001'; END IF;
 IF v_type='sesiune_deschide' THEN
  SELECT * INTO v_s FROM public.izo_preverificari WHERE uid=(v_p->>'uid')::uuid;
  IF FOUND THEN
   IF v_s.autor_profile_id<>v_uid OR v_s.proiect_id<>p_front.proiect_id OR v_s.tronson_id<>p_front.tronson_id THEN
    RAISE EXCEPTION 'ref_alt_autor' USING ERRCODE='IZ001'; END IF;
   RETURN jsonb_build_object('cod','acceptat','sesiune_id',v_s.id,'versiune',v_s.versiune);
  END IF;
  IF (v_p->>'zi')::date IS DISTINCT FROM (now() AT TIME ZONE 'Europe/Bucharest')::date THEN RAISE EXCEPTION 'zi' USING ERRCODE='IZ001'; END IF;
  INSERT INTO public.izo_preverificari(uid,proiect_id,tronson_id,autor_profile_id,dispozitiv_id)
   VALUES((v_p->>'uid')::uuid,p_front.proiect_id,p_front.tronson_id,v_uid,p_dispozitiv) RETURNING * INTO v_s;
  RETURN jsonb_build_object('cod','acceptat','sesiune_id',v_s.id,'versiune',v_s.versiune);
 END IF;
 SELECT * INTO v_s FROM public.izo_preverificari WHERE uid=(v_p->>'preverificare_uid')::uuid;
 IF NOT FOUND OR v_s.autor_profile_id<>v_uid OR v_s.proiect_id<>p_front.proiect_id OR v_s.tronson_id<>p_front.tronson_id THEN
  RAISE EXCEPTION 'ref_alt_autor' USING ERRCODE='IZ001'; END IF;
 IF v_s.stare<>'deschisa' AND NOT (v_s.stare='trimisa' AND v_type='decl_salveaza') THEN RAISE EXCEPTION 'sesiune_stare' USING ERRCODE='IZ002'; END IF;
 IF v_type='sesiune_trimite' THEN
  IF EXISTS(SELECT 1 FROM public.izo_suduri w JOIN public.izo_declaratii d ON d.id=w.declaratie_id
   WHERE d.preverificare_id=v_s.id AND w.stare='declarata'
    AND (SELECT count(*) FROM public.izo_suduri_capete c WHERE c.sudura_id=w.id AND c.activ)<>2) THEN
   RAISE EXCEPTION 'r4' USING ERRCODE='IZ002'; END IF;
  IF EXISTS(SELECT 1 FROM public.izo_declaratii WHERE preverificare_id=v_s.id AND stare IN ('conflict','blocata','revizie_ceruta')) THEN
   RAISE EXCEPTION 'rand_blocant' USING ERRCODE='IZ002'; END IF;
  IF (SELECT coalesce(jsonb_agg(jsonb_build_object('uid',uid,'versiune',versiune) ORDER BY uid),'[]'::jsonb)
    FROM public.izo_declaratii WHERE preverificare_id=v_s.id AND stare='ciorna') IS DISTINCT FROM
   (SELECT coalesce(jsonb_agg(x ORDER BY x->>'uid'),'[]'::jsonb) FROM jsonb_array_elements(v_p->'randuri') x) THEN
   RAISE EXCEPTION 'cas' USING ERRCODE='IZ002'; END IF;
  IF EXISTS(SELECT 1 FROM public.izo_declaratii d WHERE preverificare_id=v_s.id AND stare='ciorna' AND tip<>'cuplare' AND identificare IS DISTINCT FROM 'nerezolvata'
   AND NOT EXISTS(SELECT 1 FROM public.izo_rezervari r WHERE r.declaratie_id=d.id AND r.activa AND (r.expira_dupa IS NULL OR r.expira_dupa>now()))) THEN
   RAISE EXCEPTION 'rezervare_pierduta' USING ERRCODE='IZ002'; END IF;
  UPDATE public.izo_declaratii SET stare=CASE WHEN identificare='nerezolvata' THEN 'in_verificare' ELSE 'trimisa' END,
   server_ver=nextval('public.izo_server_ver_seq') WHERE preverificare_id=v_s.id AND stare='ciorna';
  UPDATE public.izo_rezervari SET expira_dupa=NULL,server_ver=nextval('public.izo_server_ver_seq') WHERE activa
   AND declaratie_id IN (SELECT id FROM public.izo_declaratii WHERE preverificare_id=v_s.id);
  UPDATE public.izo_preverificari SET stare='trimisa',trimisa_la=now(),trimisa_op_id=v_id,versiune=versiune+1,
   server_ver=nextval('public.izo_server_ver_seq') WHERE id=v_s.id;
  RETURN jsonb_build_object('cod','acceptat','sesiune_id',v_s.id);
 END IF;
 IF v_type NOT IN ('decl_salveaza','decl_sterge') THEN RAISE EXCEPTION 'tip_op' USING ERRCODE='IZ001'; END IF;
 SELECT * INTO v_d FROM public.izo_declaratii WHERE uid=(v_p->>'uid')::uuid;
 IF v_s.stare='trimisa' AND (v_d.id IS NULL OR v_d.stare NOT IN ('revizie_ceruta','conflict','blocata','in_verificare')) THEN
  RAISE EXCEPTION 'sesiune_stare' USING ERRCODE='IZ002'; END IF;
 IF FOUND THEN
  IF v_d.declarat_de<>v_uid OR v_d.preverificare_id<>v_s.id THEN RAISE EXCEPTION 'ref_alt_autor' USING ERRCODE='IZ001'; END IF;
  IF v_d.versiune IS DISTINCT FROM (v_p->>'versiune_baza')::integer OR v_d.stare NOT IN ('ciorna','conflict','blocata','in_verificare','revizie_ceruta') THEN
   RAISE EXCEPTION 'cas' USING ERRCODE='IZ002'; END IF;
 ELSE
  IF (v_p->>'versiune_baza')::integer IS DISTINCT FROM 0 OR v_type='decl_sterge' THEN RAISE EXCEPTION 'cas' USING ERRCODE='IZ002'; END IF;
 END IF;
 IF v_d.id IS NOT NULL THEN
  -- Entire author/project declaration closure was locked before any root lock.
  WITH RECURSIVE deps AS (SELECT uid FROM public.izo_declaratii WHERE depinde_de_uid=v_d.uid
   UNION SELECT d.uid FROM public.izo_declaratii d JOIN deps x ON d.depinde_de_uid=x.uid)
  UPDATE public.izo_declaratii SET stare_inainte_blocare=stare,stare='blocata',blocata_motiv=CASE WHEN v_type='decl_sterge' THEN 'dependenta_anulata' ELSE 'dependenta_in_revizie' END,server_ver=nextval('public.izo_server_ver_seq')
   WHERE uid IN (SELECT uid FROM deps) AND stare IN ('ciorna','conflict','trimisa','in_verificare','revizie_ceruta');
  UPDATE public.izo_rezervari SET activa=false,eliberata_la=now(),motiv_eliberare=CASE WHEN v_type='decl_sterge' THEN 'stearsa' ELSE 'versiune_noua' END,
   server_ver=nextval('public.izo_server_ver_seq') WHERE declaratie_id=v_d.id AND activa;
  UPDATE public.izo_suduri_capete c SET activ=false,server_ver=nextval('public.izo_server_ver_seq') WHERE c.activ AND c.sudura_id IN (SELECT s.id FROM public.izo_suduri s WHERE s.declaratie_id=v_d.id AND s.stare='declarata');
  UPDATE public.izo_suduri SET stare='anulata',server_ver=nextval('public.izo_server_ver_seq') WHERE declaratie_id=v_d.id AND stare='declarata';
  UPDATE public.izo_bucati_declarate SET stare='anulata',server_ver=nextval('public.izo_server_ver_seq') WHERE declaratie_id=v_d.id AND stare='declarata';
 END IF;
 IF v_type='decl_sterge' THEN
  UPDATE public.izo_declaratii SET stare='stearsa',stare_inainte_blocare=NULL,blocata_motiv=NULL,versiune=versiune+1,ultimul_op_id=v_id,
   server_ver=nextval('public.izo_server_ver_seq') WHERE id=v_d.id RETURNING * INTO v_d;
  INSERT INTO public.izo_declaratii_versiuni(declaratie_id,versiune,payload,hash_cerere,op_id) VALUES(v_d.id,v_d.versiune,v_p,p_hash,v_id);
  RETURN jsonb_build_object('cod','acceptat','uid',v_d.uid,'versiune',v_d.versiune,'stare',v_d.stare);
 END IF;
 IF v_p->>'tip' NOT IN ('montaj','taiere','cuplare') OR v_p->>'tip' IS NULL THEN
  RAISE EXCEPTION 'necesita_suduri_capete_E4b2' USING ERRCODE='IZ001'; END IF;
 IF v_p ? 'depinde_de_uid' THEN
  IF NOT EXISTS(SELECT 1 FROM public.izo_declaratii WHERE uid=(v_p->>'depinde_de_uid')::uuid AND declarat_de=v_uid
   AND proiect_id=p_front.proiect_id AND tronson_id=p_front.tronson_id AND versiune=(v_p->>'depinde_de_versiune')::integer
   AND stare IN ('ciorna','trimisa','aprobata')) THEN RAISE EXCEPTION 'dependenta' USING ERRCODE='IZ003'; END IF;
  IF (v_p->>'depinde_de_uid')::uuid=(v_p->>'uid')::uuid THEN RAISE EXCEPTION 'ciclu' USING ERRCODE='IZ001'; END IF;
  IF EXISTS(WITH RECURSIVE parinti AS (
   SELECT uid,depinde_de_uid FROM public.izo_declaratii WHERE uid=(v_p->>'depinde_de_uid')::uuid
   UNION SELECT d.uid,d.depinde_de_uid FROM public.izo_declaratii d JOIN parinti p ON d.uid=p.depinde_de_uid)
   SELECT 1 FROM parinti WHERE uid=(v_p->>'uid')::uuid) THEN RAISE EXCEPTION 'ciclu' USING ERRCODE='IZ001'; END IF;
 END IF;
 v_date:=coalesce((v_p->>'data_montaj')::date,(now() AT TIME ZONE 'Europe/Bucharest')::date);
 IF v_date>(now() AT TIME ZONE 'Europe/Bucharest')::date THEN RAISE EXCEPTION 'data_viitoare' USING ERRCODE='IZ001'; END IF;
 SELECT * INTO STRICT v_cfg FROM public.izo_proiect_config WHERE proiect_id=p_front.proiect_id;
 IF v_p->>'tip'<>'cuplare' THEN
 v_ref:=CASE WHEN v_p->>'tip'='taiere' THEN v_p->'sursa' ELSE v_p->'bucata' END;
 v_source:=(v_ref->>'bucata_id')::bigint; v_decl:=(v_ref->>'decl_uid')::uuid;
 IF num_nonnulls(v_source,v_decl)>1 THEN RAISE EXCEPTION 'resursa' USING ERRCODE='IZ001'; END IF;
 IF v_decl IS NOT NULL THEN
  SELECT * INTO v_c FROM public.izo_bucati_declarate WHERE uid=v_decl;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.izo_declaratii WHERE id=v_c.declaratie_id AND declarat_de=v_uid
   AND proiect_id=p_front.proiect_id AND tronson_id=p_front.tronson_id AND uid=(v_p->>'depinde_de_uid')::uuid
   AND versiune=(v_p->>'depinde_de_versiune')::integer AND stare IN ('ciorna','trimisa','aprobata')) THEN
   RAISE EXCEPTION 'ref_alt_autor' USING ERRCODE='IZ001'; END IF;
  SELECT id INTO v_source FROM public.magazie_bucati WHERE uid=v_decl;
  IF v_source IS NOT NULL THEN v_decl:=NULL;
  ELSIF v_c.stare<>'declarata' OR v_c.destinatie<>'montaj' THEN RAISE EXCEPTION 'copil_indisponibil' USING ERRCODE='IZ002'; END IF;
 END IF;
 IF v_source IS NOT NULL THEN
  SELECT * INTO v_b FROM public.magazie_bucati WHERE id=v_source;
  IF NOT FOUND OR v_b.proiect_id<>p_front.proiect_id OR v_b.tip_cod IS NULL THEN RAISE EXCEPTION 'bucata' USING ERRCODE='IZ001'; END IF;
  IF v_b.stare='carantina' THEN RAISE EXCEPTION 'carantina' USING ERRCODE='IZ001'; END IF;
  IF NOT (v_b.stare IN ('pe_tronson','montata') AND (v_b.stare<>'montata' OR v_p->>'tip'='taiere') AND v_b.tronson_id=p_front.tronson_id OR v_b.stare IN ('sosit','receptionat','retur') AND v_b.depozit_id IS NOT NULL) THEN
   RAISE EXCEPTION 'stare_bucata' USING ERRCODE='IZ002'; END IF;
  v_root:=coalesce(v_b.radacina_id,v_b.id); v_len:=v_b.lungime_mm;
  IF cardinality(public.fn_izo_pv_lipsa(ARRAY[v_root]))>0 THEN RAISE EXCEPTION 'fara_pv' USING ERRCODE='IZ001'; END IF;
  IF v_b.stare='pe_tronson' AND EXISTS(SELECT 1 FROM public.magazie_bucati_miscari m JOIN public.magazie_bucati_evenimente e ON e.id=m.eveniment_id
   WHERE m.bucata_id=v_source AND e.tip='livrare' AND (e.ora_server AT TIME ZONE 'Europe/Bucharest')::date>v_date) THEN
   RAISE EXCEPTION 'data_inainte_iesire' USING ERRCODE='IZ001'; END IF;
 ELSE
  v_root:=v_c.radacina_id; v_len:=v_c.lungime_mm;
  IF v_root IS NOT NULL THEN SELECT * INTO v_b FROM public.magazie_bucati WHERE id=v_root; END IF;
 END IF;
 IF v_source IS NULL AND v_decl IS NULL THEN
  IF v_p->>'tip'<>'montaj' OR length(coalesce(v_p->>'serie_bruta',''))=0 OR (v_p->>'lungime_masurata_mm')::integer IS NULL THEN
   RAISE EXCEPTION 'identificare' USING ERRCODE='IZ001'; END IF;
  v_ident:='nerezolvata'; v_len:=(v_p->>'lungime_masurata_mm')::integer;
 ELSE v_ident:=CASE WHEN v_decl IS NULL THEN 'bucata' ELSE 'bucata_decl' END; END IF;
 IF v_len IS NULL OR v_len<=0 OR v_len>v_cfg.lungime_max_mm THEN RAISE EXCEPTION 'lungime' USING ERRCODE='IZ001'; END IF;
 IF coalesce(v_p#>>'{confirmare,mod}','') NOT IN ('marcaj','marcaj_diferit','masurat','taiata') THEN RAISE EXCEPTION 'lungime_neconfirmata' USING ERRCODE='IZ001'; END IF;
 IF v_p#>>'{confirmare,mod}'='marcaj' AND (v_p#>>'{confirmare,cm}')::integer IS DISTINCT FROM (round(v_len::numeric/10)::integer % 100) THEN
  RAISE EXCEPTION 'confirmare_cm' USING ERRCODE='IZ001'; END IF;
 IF v_p->>'tip'='montaj' THEN
  IF v_p#>>'{confirmare,mod}' IN ('masurat','marcaj_diferit') AND abs(coalesce((v_p#>>'{confirmare,masurata_mm}')::integer,(v_p->>'lungime_masurata_mm')::integer,v_len)-v_len)>v_cfg.toleranta_mm
   AND (v_source IS DISTINCT FROM v_root OR EXISTS(SELECT 1 FROM public.magazie_bucati b WHERE b.parinte_id=v_source)
    OR EXISTS(SELECT 1 FROM public.izo_bucati_declarate c WHERE c.radacina_id=v_root AND c.declaratie_id IS DISTINCT FROM v_d.id AND c.stare<>'anulata')) THEN
   v_state:='conflict'; v_conflict:='corectie_in_arbore'; END IF;
  -- Sudura si cele doua capete se valideaza dupa identitatea declaratiei.
  IF (v_p->>'lungime_montata_mm')::integer IS NULL OR (v_p->>'lungime_montata_mm')::integer<>(CASE WHEN v_p#>>'{confirmare,mod}' ='marcaj_diferit' OR v_p#>>'{confirmare,mod}'='masurat' AND abs(coalesce((v_p#>>'{confirmare,masurata_mm}')::integer,(v_p->>'lungime_masurata_mm')::integer,v_len)-v_len)>v_cfg.toleranta_mm THEN coalesce((v_p#>>'{confirmare,masurata_mm}')::integer,(v_p->>'lungime_masurata_mm')::integer) ELSE v_len END) THEN RAISE EXCEPTION 'montaj_lungime' USING ERRCODE='IZ001'; END IF;
 ELSE
  v_base:=(v_p->>'baza_mm')::integer;
  IF v_base IS NULL OR v_base<=0 OR v_base>v_cfg.lungime_max_mm THEN RAISE EXCEPTION 'baza' USING ERRCODE='IZ001'; END IF;
  IF abs(v_base-v_len)>v_cfg.toleranta_mm AND (v_source IS DISTINCT FROM v_root OR EXISTS
   (SELECT 1 FROM public.magazie_bucati WHERE radacina_id=v_root AND id<>v_root AND stare<>'anulata') OR EXISTS
   (SELECT 1 FROM public.izo_bucati_declarate WHERE radacina_id=v_root AND declaratie_id IS DISTINCT FROM v_d.id AND stare<>'anulata')) THEN
   v_state:='conflict'; v_conflict:='corectie_in_arbore'; END IF;
  SELECT array_agg(value::integer ORDER BY ordinality) INTO v_points FROM jsonb_array_elements_text(v_p->'puncte_mm') WITH ORDINALITY;
  v_n:=jsonb_array_length(v_p->'copii');
  IF cardinality(v_points) NOT BETWEEN 1 AND 2 OR v_n IS DISTINCT FROM cardinality(v_points)+1 OR v_points[1]<=0
   OR v_points[cardinality(v_points)]>=v_base OR (cardinality(v_points)=2 AND v_points[1]>=v_points[2]) THEN RAISE EXCEPTION 'puncte' USING ERRCODE='IZ001'; END IF;
  v_sum:=0; v_i:=0;
  FOR v_child IN SELECT value FROM jsonb_array_elements(v_p->'copii') LOOP
   v_i:=v_i+1;
   v_len:=(v_child->>'lungime_mm')::integer;
   IF v_len IS NULL OR v_len<=0 OR v_len IS DISTINCT FROM
    (CASE WHEN v_i=v_n THEN v_base ELSE v_points[v_i] END)-(CASE WHEN v_i=1 THEN 0 ELSE v_points[v_i-1] END) THEN RAISE EXCEPTION 'r3' USING ERRCODE='IZ001'; END IF;
   v_sum:=v_sum+v_len;
   IF v_child->>'destinatie' NOT IN ('montaj','ramane_montat','depozit') OR v_child->>'destinatie' IS NULL THEN RAISE EXCEPTION 'destinatie' USING ERRCODE='IZ001'; END IF;
   IF EXISTS(SELECT 1 FROM public.magazie_bucati WHERE uid=(v_child->>'uid')::uuid) OR EXISTS
    (SELECT 1 FROM public.izo_bucati_declarate WHERE uid=(v_child->>'uid')::uuid AND
     (declaratie_id IS DISTINCT FROM v_d.id OR radacina_id IS DISTINCT FROM v_root OR parinte_bucata_id IS DISTINCT FROM v_source OR parinte_decl_uid IS DISTINCT FROM v_decl)) THEN RAISE EXCEPTION 'uid_alt_arbore' USING ERRCODE='IZ002'; END IF;
   IF EXISTS(SELECT 1 FROM public.magazie_bucati b WHERE b.proiect_id=p_front.proiect_id AND b.id IS DISTINCT FROM v_source AND b.stare NOT IN ('taiata','anulata')
    AND b.serie_canon=v_b.serie_canon AND b.sarja IS NOT DISTINCT FROM v_b.sarja AND b.lungime_cm=round(v_len::numeric/10)::integer) THEN
    v_state:='conflict'; v_conflict:='r1d'; END IF;
   IF (SELECT count(*) FROM jsonb_array_elements(v_p->'copii') c WHERE round((c->>'lungime_mm')::numeric/10)=round(v_len::numeric/10))>1 OR EXISTS
    (SELECT 1 FROM public.izo_bucati_declarate c JOIN public.magazie_bucati b ON b.id=c.radacina_id
     WHERE c.stare='declarata' AND c.declaratie_id IS DISTINCT FROM v_d.id AND c.uid IS DISTINCT FROM v_decl
      AND b.serie_canon=v_b.serie_canon AND b.sarja IS NOT DISTINCT FROM v_b.sarja AND round(c.lungime_mm::numeric/10)=round(v_len::numeric/10)) THEN
    v_state:='conflict'; v_conflict:='r1d'; END IF;
  END LOOP;
  IF v_sum<>v_base THEN RAISE EXCEPTION 'r3' USING ERRCODE='IZ001'; END IF;
 END IF;
 END IF; -- montaj / taiere; cuplarea rezerva capete, nu bucati
 IF v_s.stare='trimisa' AND v_state='ciorna' THEN
  v_state:=CASE WHEN v_ident='nerezolvata' THEN 'in_verificare' ELSE 'trimisa' END;
 END IF;
 -- Stable declaration identity; no facts are written to the registry.
 IF v_d.id IS NULL THEN
  INSERT INTO public.izo_declaratii(uid,preverificare_id,proiect_id,tronson_id,tip,versiune,declarat_de,declarat_de_angajat,dispozitiv_id,ultimul_op_id,
   stare,conflict_cod,identificare,bucata_id,bucata_decl_uid,sursa_bucata_id,sursa_decl_uid,depinde_de_uid,depinde_de_versiune,payload,gps_prezent,data_montaj)
  VALUES((v_p->>'uid')::uuid,v_s.id,p_front.proiect_id,p_front.tronson_id,v_p->>'tip',1,v_uid,p_emp,p_dispozitiv,v_id,v_state,v_conflict,
   CASE WHEN v_p->>'tip'='montaj' THEN v_ident END,CASE WHEN v_p->>'tip'='montaj' THEN v_source END,CASE WHEN v_p->>'tip'='montaj' THEN v_decl END,
   CASE WHEN v_p->>'tip'='taiere' THEN v_source END,CASE WHEN v_p->>'tip'='taiere' THEN v_decl END,
   (v_p->>'depinde_de_uid')::uuid,(v_p->>'depinde_de_versiune')::integer,v_p,(p_op->'payload') ? 'gps',v_date) RETURNING * INTO v_d;
 ELSE
  IF v_d.tip<>v_p->>'tip' THEN RAISE EXCEPTION 'tip_imuabil' USING ERRCODE='IZ001'; END IF;
  UPDATE public.izo_declaratii SET versiune=versiune+1,stare=v_state,conflict_cod=v_conflict,stare_inainte_blocare=NULL,blocata_motiv=NULL,
   identificare=CASE WHEN tip='montaj' THEN v_ident END,bucata_id=CASE WHEN tip='montaj' THEN v_source END,bucata_decl_uid=CASE WHEN tip='montaj' THEN v_decl END,
   sursa_bucata_id=CASE WHEN tip='taiere' THEN v_source END,sursa_decl_uid=CASE WHEN tip='taiere' THEN v_decl END,
   depinde_de_uid=(v_p->>'depinde_de_uid')::uuid,depinde_de_versiune=(v_p->>'depinde_de_versiune')::integer,
   payload=v_p,ultimul_op_id=v_id,gps_prezent=(p_op->'payload') ? 'gps',data_montaj=v_date,
   server_ver=nextval('public.izo_server_ver_seq') WHERE id=v_d.id RETURNING * INTO v_d;
 END IF;
 IF v_source IS NOT NULL OR v_decl IS NOT NULL THEN
  UPDATE public.izo_rezervari SET activa=false,eliberata_la=now(),motiv_eliberare='expirata',server_ver=nextval('public.izo_server_ver_seq')
   WHERE activa AND expira_dupa<now() AND (bucata_id=v_source OR bucata_decl_uid=v_decl);
  INSERT INTO public.izo_rezervari(proiect_id,tronson_id,declaratie_id,declaratie_versiune,autor_profile_id,bucata_id,bucata_decl_uid,din_depozit,expira_dupa)
   VALUES(p_front.proiect_id,p_front.tronson_id,v_d.id,v_d.versiune,v_uid,v_source,v_decl,coalesce(v_b.depozit_id IS NOT NULL,false),
    CASE WHEN v_s.stare='deschisa' THEN p_front.expira_la+interval '24 hours' END);
 END IF;
 IF v_d.tip='taiere' THEN
  -- Never recycle letters, including letters of cancelled declarations.
  SELECT coalesce(max(x.n),0) INTO v_letter FROM (
   SELECT ascii(left(capat_stanga,1))-65 n FROM public.izo_bucati_declarate WHERE radacina_id=v_root
   UNION ALL SELECT ascii(left(capat_dreapta,1))-65 FROM public.izo_bucati_declarate WHERE radacina_id=v_root
   UNION ALL SELECT ascii(left(capat_stanga,1))-65 FROM public.magazie_bucati WHERE radacina_id=v_root
   UNION ALL SELECT ascii(left(capat_dreapta,1))-65 FROM public.magazie_bucati WHERE radacina_id=v_root) x;
  v_prev:=coalesce(v_c.capat_stanga,v_b.capat_stanga,'A'); v_i:=0;
  FOR v_child IN SELECT value FROM jsonb_array_elements(v_p->'copii') LOOP
   v_i:=v_i+1; v_left:=v_prev;
   IF v_i=v_n THEN v_right:=coalesce(v_c.capat_dreapta,v_b.capat_dreapta,'B');
   ELSE v_letter:=v_letter+1; IF v_letter>25 THEN RAISE EXCEPTION 'litere_epuizate' USING ERRCODE='IZ001'; END IF; v_right:=chr(65+v_letter); END IF;
   INSERT INTO public.izo_bucati_declarate(uid,declaratie_id,declaratie_versiune,parinte_bucata_id,parinte_decl_uid,radacina_id,lungime_mm,lungime_calculata,
    capat_stanga,capat_dreapta,cod_bucata,destinatie,depozit_destinatie_id)
   VALUES((v_child->>'uid')::uuid,v_d.id,v_d.versiune,v_source,v_decl,v_root,(v_child->>'lungime_mm')::integer,coalesce((v_child->>'calculata')::boolean,false),
    v_left,v_right,v_left||v_right,v_child->>'destinatie',(v_child->>'depozit_destinatie_id')::integer)
   ON CONFLICT(uid) DO UPDATE SET declaratie_versiune=excluded.declaratie_versiune,lungime_mm=excluded.lungime_mm,
    lungime_calculata=excluded.lungime_calculata,
    capat_stanga=CASE WHEN izo_bucati_declarate.lungime_mm=excluded.lungime_mm THEN izo_bucati_declarate.capat_stanga ELSE excluded.capat_stanga END,
    capat_dreapta=CASE WHEN izo_bucati_declarate.lungime_mm=excluded.lungime_mm THEN izo_bucati_declarate.capat_dreapta ELSE excluded.capat_dreapta END,
    cod_bucata=CASE WHEN izo_bucati_declarate.lungime_mm=excluded.lungime_mm THEN izo_bucati_declarate.cod_bucata ELSE excluded.cod_bucata END,
    destinatie=excluded.destinatie,depozit_destinatie_id=excluded.depozit_destinatie_id,stare='declarata',server_ver=nextval('public.izo_server_ver_seq');
   IF v_child->>'destinatie'='ramane_montat' THEN
    INSERT INTO public.izo_rezervari(proiect_id,tronson_id,declaratie_id,declaratie_versiune,autor_profile_id,bucata_decl_uid,din_depozit,expira_dupa)
    VALUES(p_front.proiect_id,p_front.tronson_id,v_d.id,v_d.versiune,v_uid,(v_child->>'uid')::uuid,false,
     CASE WHEN v_s.stare='deschisa' THEN p_front.expira_la+interval '24 hours' END);
   END IF;
   v_prev:=v_right;
  END LOOP;
 END IF;
 PERFORM public.fn_izo_sudura_decl(v_d.id);
 PERFORM public.fn_izo_taiere_ramura(v_d.id);
 -- A changed/disappeared child cannot keep its old consumer reservation.
 -- Rezervarea proprie a taierii tine copilul ramane_montat, nu consuma
 -- lungimea lui: baza_mm a taierii este lungimea parintelui. Comparam doar
 -- consumatorii distincti; anularea copilului elibereaza orice rezervare.
 UPDATE public.izo_rezervari r SET activa=false,eliberata_la=now(),motiv_eliberare='parinte_anulat',
  server_ver=nextval('public.izo_server_ver_seq') WHERE r.activa AND r.bucata_decl_uid IN
   (SELECT c.uid FROM public.izo_bucati_declarate c WHERE c.declaratie_id=v_d.id AND
    (c.stare='anulata' OR EXISTS(SELECT 1 FROM public.izo_declaratii d WHERE d.id=r.declaratie_id AND d.id<>c.declaratie_id
      AND coalesce((d.payload->>'lungime_montata_mm')::integer,(d.payload->>'baza_mm')::integer) IS DISTINCT FROM c.lungime_mm)));
 -- Keep the severe reason; only unchanged referenced children can restore a row.
 UPDATE public.izo_declaratii d SET blocata_motiv='dependenta_anulata',server_ver=nextval('public.izo_server_ver_seq')
 WHERE d.stare='blocata' AND d.depinde_de_uid=v_d.uid AND EXISTS
  (SELECT 1 FROM public.izo_bucati_declarate c WHERE c.declaratie_id=v_d.id AND c.uid IN (d.bucata_decl_uid,d.sursa_decl_uid)
    AND (c.stare='anulata' OR coalesce((d.payload->>'lungime_montata_mm')::integer,(d.payload->>'baza_mm')::integer) IS DISTINCT FROM c.lungime_mm));
 IF v_d.stare='trimisa' THEN
  -- Iterate in dependency order; a transitive descendant waits for its parent.
  LOOP
   UPDATE public.izo_declaratii d SET stare=d.stare_inainte_blocare,stare_inainte_blocare=NULL,blocata_motiv=NULL,
    depinde_de_versiune=p.versiune,server_ver=nextval('public.izo_server_ver_seq')
   FROM public.izo_declaratii p WHERE d.depinde_de_uid=p.uid AND d.proiect_id=p_front.proiect_id AND d.declarat_de=v_uid
    AND d.id=ANY(public.fn_izo_dependenti(v_d.id))
    AND d.stare='blocata' AND d.blocata_motiv='dependenta_in_revizie' AND p.stare IN ('trimisa','ciorna','conflict')
    AND (coalesce(d.bucata_decl_uid,d.sursa_decl_uid) IS NULL OR EXISTS(SELECT 1 FROM public.izo_bucati_declarate c
     WHERE c.uid=coalesce(d.bucata_decl_uid,d.sursa_decl_uid) AND c.declaratie_id=p.id AND c.stare='declarata'
      AND c.lungime_mm=coalesce((d.payload->>'lungime_montata_mm')::integer,(d.payload->>'baza_mm')::integer)));
   GET DIAGNOSTICS v_affected=ROW_COUNT; EXIT WHEN v_affected=0;
  END LOOP;
 END IF;
 INSERT INTO public.izo_declaratii_versiuni(declaratie_id,versiune,payload,hash_cerere,op_id) VALUES(v_d.id,v_d.versiune,v_p,p_hash,v_id);
 IF (p_op->'payload') ? 'gps' THEN
  v_gps:=p_op#>'{payload,gps}';
  IF jsonb_typeof(v_gps)<>'object' OR v_gps-ARRAY['lat','lon','precizie_m','la']<>'{}'::jsonb THEN RAISE EXCEPTION 'gps' USING ERRCODE='IZ001'; END IF;
  INSERT INTO public.izo_declaratii_gps(declaratie_id,versiune,lat,lon,precizie_m,la)
   VALUES(v_d.id,v_d.versiune,(v_gps->>'lat')::numeric,(v_gps->>'lon')::numeric,(v_gps->>'precizie_m')::numeric,(v_gps->>'la')::timestamptz);
 END IF;
 RETURN jsonb_build_object('cod','acceptat','uid',v_d.uid,'versiune',v_d.versiune,'stare',v_d.stare,'conflict_cod',v_d.conflict_cod);
END $f$;

  CREATE FUNCTION public.fn_izo_teren_push(p_dispozitiv uuid,p_ops jsonb) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_f public.izo_fronturi; v_old public.izo_operatii; v_uid uuid; v_emp bigint;
 v_op jsonb; v_p jsonb; v_results jsonb:='[]'; v_response jsonb; v_hash text;
 v_code text; v_result text; v_state text; v_pr bigint; v_tr bigint; v_seq bigint:=0; v_last bigint;
 v_opid uuid; v_ora timestamptz; v_deps uuid[]:='{}'; v_stop boolean:=false; v_format integer;
BEGIN
 -- No table read or write precedes the schema lock.
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ COMMITTED' USING ERRCODE='25001'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
 IF session_user<>'authenticator' OR public.fn_izo_jwt_rol() IS DISTINCT FROM 'authenticated' OR public.fn_izo_uid() IS NULL THEN
  RETURN jsonb_build_object('cod','fara_drept'); END IF;
 IF jsonb_typeof(p_ops) IS DISTINCT FROM 'array' OR jsonb_array_length(p_ops) NOT BETWEEN 1 AND 50 OR octet_length(p_ops::text)>262144 THEN
  RETURN jsonb_build_object('cod','limita'); END IF;
 v_uid:=public.fn_izo_uid();
 BEGIN
  v_pr:=(p_ops#>>'{0,payload,proiect_id}')::bigint; v_tr:=(p_ops#>>'{0,payload,tronson_id}')::bigint;
  IF v_pr IS NULL OR v_tr IS NULL OR p_dispozitiv IS NULL THEN RETURN jsonb_build_object('cod','eroare','motiv','lot_format'); END IF;
  FOR v_op IN SELECT value FROM jsonb_array_elements(p_ops) LOOP
   IF jsonb_typeof(v_op)<>'object' OR v_op-ARRAY['op_id','seq','tip_op','ora_tableta','payload','versiune_format']<>'{}'::jsonb
    OR (v_op#>>'{payload,proiect_id}')::bigint IS DISTINCT FROM v_pr OR (v_op#>>'{payload,tronson_id}')::bigint IS DISTINCT FROM v_tr
    OR (v_op->>'seq')::bigint IS NULL OR (v_op->>'seq')::bigint<=v_seq OR (v_op->>'op_id')::uuid IS NULL THEN
    RETURN jsonb_build_object('cod','eroare','motiv','lot_format'); END IF;
   v_seq:=(v_op->>'seq')::bigint;
  END LOOP;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN jsonb_build_object('cod','eroare','motiv','lot_format'); END;
 v_code:=public.fn_izo_teren_entra(v_pr,'sync');
 IF v_code IS NOT NULL THEN RETURN jsonb_build_object('cod',v_code); END IF;
 SELECT * INTO v_f FROM public.izo_fronturi WHERE tronson_id=v_tr AND activ FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('cod','front_expirat'); END IF;
 IF v_f.proiect_id<>v_pr THEN RETURN jsonb_build_object('cod','fara_drept'); END IF;
 PERFORM 1 FROM public.izo_preverificari WHERE proiect_id=v_pr AND autor_profile_id=v_uid ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.izo_declaratii WHERE proiect_id=v_pr AND declarat_de=v_uid ORDER BY id FOR UPDATE;
 v_emp:=public.fn_izo_teren_autorizat(v_pr,true);
 IF v_emp IS NULL THEN RETURN jsonb_build_object('cod','fara_drept'); END IF;
 IF v_f.profile_id<>v_uid OR v_f.dispozitiv_id<>p_dispozitiv THEN
  FOR v_op IN SELECT value FROM jsonb_array_elements(p_ops) LOOP
   BEGIN
    v_p:=public.fn_izo_teren_payload(v_op->'payload');
    INSERT INTO public.izo_sync_incercari(proiect_id,tronson_id,autor_profile_id,op_id,dispozitiv_id,tip_op,payload)
     VALUES(v_pr,v_tr,v_uid,(v_op->>'op_id')::uuid,p_dispozitiv,v_op->>'tip_op',v_p) ON CONFLICT DO NOTHING;
   EXCEPTION WHEN SQLSTATE 'IZ001' THEN NULL; END;
   v_results:=v_results||jsonb_build_array(jsonb_build_object('op_id',v_op->>'op_id','cod','alt_dispozitiv'));
  END LOOP;
  RETURN jsonb_build_object('cod','alt_dispozitiv','rezultate',v_results);
 END IF;
 IF v_f.expira_la<=now() THEN RETURN jsonb_build_object('cod','front_expirat'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.izo_dispozitive WHERE dispozitiv_id=p_dispozitiv AND profile_id=v_uid) THEN RETURN jsonb_build_object('cod','fara_drept'); END IF;
 -- Conservative, fixed superset of the transitive closure: all this author's project rows.
 -- It also contains dependencies introduced by earlier operations in the same batch.
 PERFORM 1 FROM public.izo_tronson_config WHERE tronson_id=v_tr AND proiect_id=v_pr FOR SHARE;
 PERFORM public.fn_izo_blocheaza_locuri(v_pr,ARRAY(SELECT DISTINCT depozit_id FROM public.magazie_bucati WHERE proiect_id=v_pr AND depozit_id IS NOT NULL ORDER BY depozit_id),ARRAY[v_tr]);
 IF NOT EXISTS(SELECT 1 FROM public.izo_tronson_config WHERE tronson_id=v_tr AND proiect_id=v_pr AND flux_montaj)
  OR coalesce(public.fn_izo_nivel(v_pr),'off') NOT IN ('stoc','montaj') THEN RETURN jsonb_build_object('cod','fara_drept'); END IF;
 -- No project advisory: roots serialize reservation races across fronts (§10.5).
 PERFORM 1 FROM public.magazie_bucati WHERE proiect_id=v_pr AND tip_cod IS NOT NULL AND id=radacina_id ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.magazie_bucati WHERE proiect_id=v_pr AND tip_cod IS NOT NULL ORDER BY id FOR UPDATE;
 SELECT ultimul_seq INTO v_last FROM public.izo_dispozitive WHERE dispozitiv_id=p_dispozitiv FOR UPDATE;
 IF (SELECT count(*) FROM public.izo_operatii WHERE autor_profile_id=v_uid AND ora_server>now()-interval '1 hour')+jsonb_array_length(p_ops)>600 THEN
  RETURN jsonb_build_object('cod','limita'); END IF;
 FOR v_op IN SELECT value FROM jsonb_array_elements(p_ops) LOOP
  v_opid:=(v_op->>'op_id')::uuid; v_seq:=(v_op->>'seq')::bigint;
  v_format:=CASE WHEN coalesce(v_op->>'versiune_format','') ~ '^[0-9]{1,8}$' THEN (v_op->>'versiune_format')::integer ELSE 0 END;
  v_hash:=encode(sha256(convert_to(jsonb_build_object('dispozitiv_id',p_dispozitiv,'cerere',v_op)::text,'UTF8')),'hex');
  SELECT * INTO v_old FROM public.izo_operatii WHERE autor_profile_id=v_uid AND op_id=v_opid;
  IF FOUND THEN
   v_response:=CASE WHEN v_old.canal='teren' AND v_old.hash_cerere=v_hash
    THEN jsonb_build_object('cod','duplicat','raspuns',v_old.raspuns) ELSE jsonb_build_object('cod','conflict_op') END;
   v_results:=v_results||jsonb_build_array(jsonb_build_object('op_id',v_opid)||v_response); CONTINUE;
  END IF;
  v_response:=NULL; v_result:='acceptat'; v_code:=NULL; v_p:='{}'; v_ora:=NULL;
  BEGIN
   v_p:=public.fn_izo_teren_payload(v_op->'payload');
   v_ora:=(v_op->>'ora_tableta')::timestamptz;
   IF (v_p->>'depinde_de_uid')::uuid=ANY(v_deps) OR EXISTS(SELECT 1 FROM public.izo_declaratii
    WHERE uid=(v_p->>'depinde_de_uid')::uuid AND stare IN ('conflict','blocata')) THEN
    v_response:=jsonb_build_object('cod','blocat_de_conflict');
   ELSE
    IF v_op->>'tip_op'='decl_salveaza' AND (v_p->>'versiune_baza')::integer=0 AND
     ((SELECT count(*) FROM public.izo_rezervari WHERE autor_profile_id=v_uid AND activa AND (expira_dupa IS NULL OR expira_dupa>now()))>=60
     OR ((SELECT count(*) FROM public.izo_rezervari WHERE autor_profile_id=v_uid AND activa AND din_depozit AND (expira_dupa IS NULL OR expira_dupa>now()))>=10
      AND EXISTS(SELECT 1 FROM public.magazie_bucati WHERE id=coalesce((v_p#>>'{bucata,bucata_id}')::bigint,(v_p#>>'{sursa,bucata_id}')::bigint) AND depozit_id IS NOT NULL))) THEN
     v_response:=jsonb_build_object('cod','limita');
    ELSIF v_op->>'tip_op'='decl_salveaza' AND (v_p->>'versiune_baza')::integer=0 AND
     (SELECT count(*) FROM public.izo_declaratii d JOIN public.izo_preverificari s ON s.id=d.preverificare_id WHERE s.uid=(v_p->>'preverificare_uid')::uuid)>=200 THEN
     v_response:=jsonb_build_object('cod','limita');
    ELSE
     v_response:=public.fn_izo_teren_op(p_dispozitiv,v_op,v_p,v_emp,v_hash,v_f);
     v_response:=v_response||jsonb_build_object('alerte',to_jsonb(array_remove(ARRAY[
      CASE WHEN abs(extract(epoch FROM now()-v_ora))>300 THEN 'izo_ceas_tableta' END,
      CASE WHEN v_seq>v_last+1 THEN 'izo_gol_operatii' END],NULL)));
     -- Journal is the LAST write of this operation's savepoint.
     INSERT INTO public.izo_operatii(autor_profile_id,op_id,canal,proiect_id,tronson_id,dispozitiv_id,seq,versiune_format,tip_op,payload,hash_cerere,rezultat,raspuns,ora_tableta,offset_ceas_s)
      VALUES(v_uid,v_opid,'teren',v_pr,v_tr,p_dispozitiv,v_seq,v_format,v_op->>'tip_op',v_p,v_hash,'acceptat',v_response,v_ora,extract(epoch FROM now()-v_ora));
    END IF;
   END IF;
  EXCEPTION
   WHEN serialization_failure OR deadlock_detected OR lock_not_available OR query_canceled THEN
    v_response:=jsonb_build_object('cod','reincearca'); v_stop:=true;
   WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_state=RETURNED_SQLSTATE;
    IF v_state='IZ003' THEN v_response:=jsonb_build_object('cod','blocat_de_conflict');
    ELSE
     v_result:=CASE WHEN v_state IN ('IZ002','23505') THEN 'conflict' WHEN left(v_state,2) IN ('IZ','22','23') THEN 'eroare' ELSE 'eroare_interna' END;
     -- Do not copy SQLERRM from arbitrary SQL: it can include submitted GPS values.
     v_code:=CASE WHEN left(v_state,2)='IZ' THEN SQLERRM ELSE v_state END;
     v_response:=jsonb_build_object('cod',v_result,'motiv',v_code);
     INSERT INTO public.izo_operatii(autor_profile_id,op_id,canal,proiect_id,tronson_id,dispozitiv_id,seq,versiune_format,tip_op,payload,hash_cerere,rezultat,cod,raspuns,ora_tableta)
      VALUES(v_uid,v_opid,'teren',v_pr,v_tr,p_dispozitiv,v_seq,v_format,coalesce(v_op->>'tip_op',''),v_p,v_hash,v_result,v_code,v_response,v_ora);
    END IF;
  END;
  IF v_response->>'cod'<>'acceptat' OR v_response->>'stare' IN ('conflict','blocata') THEN
   BEGIN v_deps:=array_append(v_deps,(v_p->>'uid')::uuid); EXCEPTION WHEN invalid_text_representation THEN NULL; END;
  END IF;
  v_results:=v_results||jsonb_build_array(jsonb_build_object('op_id',v_opid)||v_response);
  IF v_stop THEN EXIT; END IF;
  v_last:=greatest(v_last,v_seq);
 END LOOP;
 UPDATE public.izo_dispozitive SET ultimul_seq=v_last,server_ver=nextval('public.izo_server_ver_seq') WHERE dispozitiv_id=p_dispozitiv AND profile_id=v_uid;
 RETURN jsonb_build_object('cod','ok','rezultate',v_results,'server_ver_max',greatest(
  coalesce((SELECT max(server_ver) FROM public.izo_declaratii WHERE proiect_id=v_pr),0),
  coalesce((SELECT max(server_ver) FROM public.izo_rezervari WHERE proiect_id=v_pr),0)));
END $f$;
  CREATE FUNCTION public.fn_izo_sync_push(p_dispozitiv uuid,p_ops jsonb) RETURNS jsonb
 LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 SELECT public.fn_izo_teren_push(p_dispozitiv,p_ops)
$f$;

  CREATE FUNCTION public.fn_izo_gps_citeste(p_decl bigint) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_pr bigint; v_uid uuid; v_result jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ COMMITTED' USING ERRCODE='25001'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
 IF session_user<>'authenticator' OR public.fn_izo_jwt_rol() IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'fara_drept' USING ERRCODE='42501'; END IF;
 v_uid:=public.fn_izo_uid();
 SELECT proiect_id INTO v_pr FROM public.izo_declaratii WHERE id=p_decl;
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=v_uid AND employee_id IS NOT NULL AND (is_owner OR
  EXISTS(SELECT 1 FROM public.izo_atribuiri WHERE profile_id=v_uid AND proiect_id=v_pr AND activ AND rol IN ('manager_aprobator','inlocuitor_aprobator')
   AND current_date BETWEEN valabil_de AND coalesce(valabil_pana,current_date)))) THEN RAISE EXCEPTION 'fara_drept' USING ERRCODE='42501'; END IF;
 IF cardinality(public.fn_izo_porti_lipsa())<>0 THEN RAISE EXCEPTION 'E4b porti'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(g) ORDER BY versiune),'[]'::jsonb) INTO v_result FROM public.izo_declaratii_gps g WHERE declaratie_id=p_decl;
 RETURN v_result;
END $f$;
  CREATE FUNCTION public.fn_izo_teren_pregateste(p_proiect bigint,p_tronson bigint,p_dispozitiv uuid) RETURNS jsonb
 LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 SELECT public.fn_izo_teren_intern(p_proiect,p_tronson,p_dispozitiv,true)
$f$;

-- E4b-2. API wrappers are deliberately thin; all helpers are private.
  CREATE FUNCTION public.fn_izo_autor_valabil(p_autor uuid,p_proiect bigint,p_lock boolean) RETURNS boolean
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_owner boolean; v_emp bigint;
BEGIN
 IF p_lock THEN
  SELECT is_owner,employee_id INTO v_owner,v_emp FROM public.profiles WHERE id=p_autor FOR SHARE;
 ELSE SELECT is_owner,employee_id INTO v_owner,v_emp FROM public.profiles WHERE id=p_autor; END IF;
 IF v_emp IS NULL THEN RETURN false; END IF;
 IF v_owner THEN RETURN true; END IF;
 IF p_lock THEN
  PERFORM 1 FROM public.user_module_access WHERE profile_id=p_autor AND module='executie.izometrie'
   AND access_level IN ('editor','admin') ORDER BY id FOR SHARE;
 ELSE
  PERFORM 1 FROM public.user_module_access WHERE profile_id=p_autor AND module='executie.izometrie' AND access_level IN ('editor','admin');
 END IF;
 IF NOT FOUND THEN RETURN false; END IF;
 IF p_lock THEN
  PERFORM 1 FROM public.izo_atribuiri WHERE profile_id=p_autor AND proiect_id=p_proiect AND rol='inginer_izometrie'
   AND activ AND current_date BETWEEN valabil_de AND coalesce(valabil_pana,current_date) ORDER BY id FOR SHARE;
 ELSE
  PERFORM 1 FROM public.izo_atribuiri WHERE profile_id=p_autor AND proiect_id=p_proiect AND rol='inginer_izometrie'
   AND activ AND current_date BETWEEN valabil_de AND coalesce(valabil_pana,current_date);
 END IF;
 RETURN FOUND;
END $f$;

  CREATE FUNCTION public.fn_izo_birou_autorizat(p_proiect bigint,p_depozit integer,p_lock boolean) RETURNS bigint
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_emp bigint; v_owner boolean; v_uid uuid:=public.fn_izo_uid();
BEGIN
 IF p_lock THEN
  SELECT employee_id,is_owner INTO v_emp,v_owner FROM public.profiles WHERE id=v_uid FOR SHARE;
 ELSE SELECT employee_id,is_owner INTO v_emp,v_owner FROM public.profiles WHERE id=v_uid; END IF;
 IF v_emp IS NULL THEN RAISE EXCEPTION 'fara_drept' USING ERRCODE='42501'; END IF;
 IF v_owner THEN RETURN v_emp; END IF;
 -- Reuse the deployed access contract; no access/module data is introduced here.
 IF p_depozit IS NULL THEN
  IF NOT (public.fn_izo_acces(p_proiect,'executie.izometrie','editor','manager_aprobator')
    OR public.fn_izo_acces(p_proiect,'executie.izometrie','editor','inlocuitor_aprobator')) THEN
   RAISE EXCEPTION 'fara_drept' USING ERRCODE='42501'; END IF;
 ELSE
  IF NOT public.fn_izo_acces(p_proiect,'magazie','editor','gestionar') THEN RAISE EXCEPTION 'fara_drept' USING ERRCODE='42501'; END IF;
 END IF;
 IF p_lock THEN
  PERFORM 1 FROM public.user_module_access WHERE profile_id=v_uid
   AND module=(CASE WHEN p_depozit IS NULL THEN 'executie.izometrie' ELSE 'magazie' END)
   AND access_level IN ('editor','admin') ORDER BY id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'fara_drept' USING ERRCODE='42501'; END IF;
 END IF;
 IF p_lock THEN
  PERFORM 1 FROM public.izo_atribuiri WHERE profile_id=v_uid AND proiect_id=p_proiect AND activ
   AND current_date BETWEEN valabil_de AND coalesce(valabil_pana,current_date)
   AND ((p_depozit IS NULL AND rol IN ('manager_aprobator','inlocuitor_aprobator') AND depozit_id IS NULL)
     OR (p_depozit IS NOT NULL AND rol='gestionar' AND depozit_id=p_depozit)) ORDER BY id FOR SHARE;
 ELSE
  PERFORM 1 FROM public.izo_atribuiri WHERE profile_id=v_uid AND proiect_id=p_proiect AND activ
   AND current_date BETWEEN valabil_de AND coalesce(valabil_pana,current_date)
   AND ((p_depozit IS NULL AND rol IN ('manager_aprobator','inlocuitor_aprobator') AND depozit_id IS NULL)
     OR (p_depozit IS NOT NULL AND rol='gestionar' AND depozit_id=p_depozit));
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'fara_drept' USING ERRCODE='42501'; END IF;
 RETURN v_emp;
END $f$;

  CREATE FUNCTION public.fn_izo_birou_intrare(p_proiect bigint,p_depozit integer) RETURNS void
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_lipsa text[];
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ COMMITTED' USING ERRCODE='25001'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
 IF session_user<>'authenticator' OR public.fn_izo_jwt_rol() IS DISTINCT FROM 'authenticated' OR public.fn_izo_uid() IS NULL THEN
  RAISE EXCEPTION 'fara_drept' USING ERRCODE='42501'; END IF;
 IF coalesce(current_setting('izo.montaj_ctx',true),'')<>'' OR coalesce(current_setting('izo.receptie_ctx',true),'')<>''
  OR coalesce(current_setting('izo.registru_tx',true),'')<>'' THEN RAISE EXCEPTION 'context_ocupat' USING ERRCODE='42501'; END IF;
 PERFORM public.fn_izo_birou_autorizat(p_proiect,p_depozit,false);
 v_lipsa:=public.fn_izo_porti_lipsa();
 IF cardinality(v_lipsa)>0 THEN RAISE EXCEPTION 'E4b porti %',v_lipsa; END IF;
END $f$;

-- Runs AS the existing E4 registry writer, never as postgres. Typed snapshots and
-- exact event/movement images are checked by the existing registry guards.
  CREATE FUNCTION public.fn_izo_birou_fapt(p_bucata bigint,p_op text,p_ref text,p_tronson bigint,p_depozit integer,
 p_autor uuid,p_dispozitiv text,p_ora timestamptz,p_motiv text) RETURNS bigint
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_b public.magazie_bucati; v_dupa public.magazie_bucati; v_ev public.magazie_bucati_evenimente;
 v_m public.magazie_bucati_miscari; v_ctx text; v_n bigint; v_now timestamptz:=clock_timestamp();
BEGIN
 IF current_user<>'izo_montaj_writer' OR p_op IS NULL OR p_op NOT IN ('aproba','iesire') THEN RAISE EXCEPTION 'scriitor_invalid' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT v_b FROM public.magazie_bucati WHERE id=p_bucata FOR UPDATE;
 v_dupa:=v_b; v_dupa.updated_at:=v_now; v_dupa.server_ver:=nextval('public.izo_server_ver_seq');
 IF p_op='aproba' THEN
  IF v_b.stare<>'pe_tronson' OR v_b.tronson_id IS DISTINCT FROM p_tronson THEN RAISE EXCEPTION 'stare'; END IF;
  v_dupa.stare:='montata';
 ELSE
  IF v_b.stare NOT IN ('sosit','receptionat','retur') OR v_b.depozit_id IS DISTINCT FROM p_depozit THEN RAISE EXCEPTION 'stare'; END IF;
  v_dupa.stare:='pe_tronson'; v_dupa.locatie_tip:='tronson'; v_dupa.tronson_id:=p_tronson; v_dupa.depozit_id:=NULL;
  v_dupa.atribute:=coalesce(v_b.atribute,'{}'::jsonb)||jsonb_build_object('depozit_origine_id',p_depozit);
 END IF;
 v_ctx:=concat_ws('|',txid_current()::text,p_op,p_ref,v_b.proiect_id,p_tronson,v_dupa.server_ver,v_b.id);
 PERFORM public.fn_izo_montaj_marcheaza(v_ctx,to_jsonb(v_b),to_jsonb(v_dupa),NULL);
 UPDATE public.magazie_bucati SET stare=v_dupa.stare,locatie_tip=v_dupa.locatie_tip,depozit_id=v_dupa.depozit_id,
  tronson_id=v_dupa.tronson_id,atribute=v_dupa.atribute,server_ver=v_dupa.server_ver,updated_at=v_now WHERE id=v_b.id;
 GET DIAGNOSTICS v_n=ROW_COUNT;
 IF v_n<>1 THEN RAISE EXCEPTION 'bucata_schimbata'; END IF;
 IF to_jsonb(v_dupa) IS DISTINCT FROM (SELECT to_jsonb(b) FROM public.magazie_bucati b WHERE b.id=v_b.id) THEN RAISE EXCEPTION 'reconciliere_bucata'; END IF;
 v_ev:=jsonb_populate_record(NULL::public.magazie_bucati_evenimente,jsonb_build_object(
  'tip',CASE WHEN p_op='aproba' THEN 'montaj' ELSE 'livrare' END,'proiect_id',v_b.proiect_id,
  'document_tip',CASE WHEN p_op='aproba' THEN 'izo_declaratie' ELSE 'izo_iesire' END,'document_id',p_ref,
  'motiv',p_motiv,'declarat_de',p_autor,'aplicat_de',public.fn_izo_uid(),'aplicat_rol','izo_montaj_writer',
  'ora_server',v_now,'ora_tableta',p_ora,'dispozitiv_id',p_dispozitiv,'server_ver',nextval('public.izo_server_ver_seq')));
 PERFORM public.fn_izo_montaj_marcheaza(v_ctx,NULL,NULL,jsonb_build_object('tabel','magazie_bucati_evenimente','rand',to_jsonb(v_ev)-'id'));
 INSERT INTO public.magazie_bucati_evenimente(tip,proiect_id,document_tip,document_id,import_id,storno_de_eveniment_id,motiv,
  declarat_de,aplicat_de,aplicat_rol,ora_server,ora_tableta,dispozitiv_id,server_ver)
 VALUES(v_ev.tip,v_ev.proiect_id,v_ev.document_tip,v_ev.document_id,v_ev.import_id,v_ev.storno_de_eveniment_id,v_ev.motiv,
  v_ev.declarat_de,v_ev.aplicat_de,v_ev.aplicat_rol,v_ev.ora_server,v_ev.ora_tableta,v_ev.dispozitiv_id,v_ev.server_ver) RETURNING id INTO v_ev.id;
 v_m:=jsonb_populate_record(NULL::public.magazie_bucati_miscari,jsonb_build_object('eveniment_id',v_ev.id,'proiect_id',v_b.proiect_id,
  'bucata_id',v_b.id,'rol',CASE WHEN p_op='aproba' THEN 'montat' ELSE 'mutat' END,'stare_inainte',v_b.stare,'stare_dupa',v_dupa.stare,
  'din_loc',jsonb_build_object('depozit_id',v_b.depozit_id,'tronson_id',v_b.tronson_id),
  'in_loc',jsonb_build_object('depozit_id',v_dupa.depozit_id,'tronson_id',v_dupa.tronson_id),
  'lungime_mm',v_b.lungime_mm,'inainte',to_jsonb(v_b),'dupa',to_jsonb(v_dupa),'server_ver',nextval('public.izo_server_ver_seq')));
 PERFORM public.fn_izo_montaj_marcheaza(v_ctx,NULL,NULL,jsonb_build_object('tabel','magazie_bucati_miscari','rand',to_jsonb(v_m)-'id'));
 INSERT INTO public.magazie_bucati_miscari(eveniment_id,proiect_id,bucata_id,rol,stare_inainte,stare_dupa,din_loc,in_loc,lungime_mm,inainte,dupa,server_ver)
 VALUES(v_m.eveniment_id,v_m.proiect_id,v_m.bucata_id,v_m.rol,v_m.stare_inainte,v_m.stare_dupa,v_m.din_loc,v_m.in_loc,
  v_m.lungime_mm,v_m.inainte,v_m.dupa,v_m.server_ver);
 PERFORM public.fn_izo_montaj_marcheaza(NULL,NULL,NULL,NULL);
 RETURN v_ev.id;
END $f$;

  CREATE FUNCTION public.fn_izo_birou_preview(p_preverificare bigint) RETURNS jsonb
 LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 SELECT jsonb_build_object('preverificare',to_jsonb(s),'randuri',coalesce((
  SELECT jsonb_agg(jsonb_build_object('declaratie',to_jsonb(d),'rezervari',(
   SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]') FROM public.izo_rezervari r WHERE r.declaratie_id=d.id),
   'bucata',(SELECT to_jsonb(b)||jsonb_build_object('radacina',(SELECT to_jsonb(root) FROM public.magazie_bucati root WHERE root.id=coalesce(b.radacina_id,b.id)),
     'fara_pv',public.fn_izo_pv_lipsa(ARRAY[coalesce(b.radacina_id,b.id)])) FROM public.magazie_bucati b WHERE b.id=d.bucata_id),
   'copii',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.uid),'[]') FROM public.izo_bucati_declarate c WHERE c.declaratie_id=d.id)) ORDER BY d.id)
  FROM public.izo_declaratii d WHERE d.proiect_id=s.proiect_id AND d.tronson_id=s.tronson_id AND d.preverificare_id IN (SELECT p.id FROM public.izo_preverificari p WHERE p.zi=s.zi AND p.stare='trimisa')),'[]'),
  'suduri',(SELECT coalesce(jsonb_agg(to_jsonb(w) ORDER BY w.id),'[]') FROM public.izo_suduri w WHERE w.proiect_id=s.proiect_id),
  'capete',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.id),'[]') FROM public.izo_suduri_capete c JOIN public.izo_suduri w ON w.id=c.sudura_id WHERE w.proiect_id=s.proiect_id),
  'registru',(SELECT coalesce(jsonb_agg(to_jsonb(b) ORDER BY b.id),'[]') FROM public.magazie_bucati b WHERE b.proiect_id=s.proiect_id),
  'rezervari_proiect',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]') FROM public.izo_rezervari r WHERE r.proiect_id=s.proiect_id),
  'copii_proiect',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.uid),'[]') FROM public.izo_bucati_declarate c JOIN public.izo_declaratii d ON d.id=c.declaratie_id WHERE d.proiect_id=s.proiect_id),
  'sesiuni_proiect',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]') FROM public.izo_preverificari p WHERE p.proiect_id=s.proiect_id),
  'declaratii_proiect',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.id),'[]') FROM public.izo_declaratii d WHERE d.proiect_id=s.proiect_id),
  'depozite',(SELECT coalesce(jsonb_agg(to_jsonb(dep) ORDER BY dep.id),'[]') FROM public.logistica_depozite dep JOIN public.executie_proiecte pr ON pr.site_id=dep.site_id WHERE pr.id=s.proiect_id),
  'config',(SELECT to_jsonb(c) FROM public.izo_tronson_config c WHERE c.tronson_id=s.tronson_id),
  'proiect_config',(SELECT to_jsonb(c) FROM public.izo_proiect_config c WHERE c.proiect_id=s.proiect_id),
  'proiect',(SELECT to_jsonb(p) FROM public.executie_proiecte p WHERE p.id=s.proiect_id),
  'tronson',(SELECT to_jsonb(t) FROM public.executie_tronsoane t WHERE t.id=s.tronson_id))
 FROM public.izo_preverificari s WHERE s.id=p_preverificare
$f$;

  CREATE FUNCTION public.fn_izo_aprobare_intern(p_preverificare bigint) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_pr bigint; v_doc jsonb; v_sim jsonb; v_ids bigint[];
BEGIN
 -- API/isolation/schema precede the first table read.
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ COMMITTED' USING ERRCODE='25001'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
 SELECT proiect_id INTO v_pr FROM public.izo_preverificari WHERE id=p_preverificare;
 PERFORM public.fn_izo_birou_intrare(v_pr,NULL);
 v_doc:=public.fn_izo_birou_preview(p_preverificare);
 IF v_doc IS NULL THEN RAISE EXCEPTION 'sesiune_lipsa'; END IF;
 SELECT coalesce(array_agg(d.id ORDER BY d.id),'{}') INTO v_ids FROM public.izo_declaratii d
  WHERE d.preverificare_id IN (SELECT p.id FROM public.izo_preverificari p JOIN public.izo_preverificari a ON a.id=p_preverificare WHERE p.proiect_id=a.proiect_id AND p.tronson_id=a.tronson_id AND p.zi=a.zi AND p.stare='trimisa') AND d.stare='trimisa';
 BEGIN v_sim:=public.fn_izo_lot_efecte(v_ids);
 EXCEPTION WHEN raise_exception THEN v_sim:=jsonb_build_object('refuz',SQLERRM); END;
 RETURN v_doc||jsonb_build_object('amprenta',encode(sha256(convert_to(v_doc::text,'UTF8')),'hex'),'decizii_cerute',coalesce((SELECT jsonb_agg('corectie:'||d.id ORDER BY d.id) FROM public.izo_declaratii d WHERE d.id=ANY(v_ids) AND public.fn_izo_corectie_mm(d.id) IS NOT NULL),'[]'::jsonb),'simulare',v_sim);
END $f$;

  CREATE FUNCTION public.fn_izo_birou_jurnal(p_cheie uuid,p_canal text,p_tip text,p_proiect bigint,p_tronson bigint,
 p_payload jsonb,p_hash text,p_raspuns jsonb) RETURNS void
 LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 INSERT INTO public.izo_operatii(autor_profile_id,op_id,canal,proiect_id,tronson_id,dispozitiv_id,seq,versiune_format,
  tip_op,payload,hash_cerere,rezultat,raspuns)
 VALUES(public.fn_izo_uid(),p_cheie,p_canal,p_proiect,p_tronson,p_cheie,1,1,p_tip,p_payload,p_hash,'acceptat',p_raspuns)
$f$;

  CREATE FUNCTION public.fn_izo_aproba_intern(p_cheie uuid,p_preverificare bigint,p_randuri jsonb,p_amprenta text,p_decizii jsonb) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_s public.izo_preverificari; v_d public.izo_declaratii; v_b public.magazie_bucati; v_r jsonb;
 v_plan jsonb; v_id bigint; v_res public.izo_rezervari; v_child public.izo_bucati_declarate; v_expected record; v_rez_before jsonb; v_keys text[]; v_given text[]; v_mm integer; v_corr bigint;
 v_emp bigint; v_ev bigint; v_evs bigint[]:='{}'; v_ids bigint[]; v_doc jsonb; v_hash text; v_payload jsonb; v_old public.izo_operatii; v_n bigint;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ COMMITTED' USING ERRCODE='25001'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
 SELECT * INTO v_s FROM public.izo_preverificari WHERE id=p_preverificare;
 PERFORM public.fn_izo_birou_intrare(v_s.proiect_id,NULL);
 IF v_s.id IS NULL THEN RAISE EXCEPTION 'sesiune_lipsa'; END IF;
 IF p_cheie IS NULL OR jsonb_typeof(p_randuri) IS DISTINCT FROM 'array' OR jsonb_array_length(p_randuri) NOT BETWEEN 1 AND 200
  OR jsonb_typeof(p_decizii) IS DISTINCT FROM 'object' OR p_amprenta IS NULL THEN RAISE EXCEPTION 'parametri_invalizi'; END IF;
 SELECT array_agg((x->>'declaratie_id')::bigint ORDER BY (x->>'declaratie_id')::bigint) INTO v_ids FROM jsonb_array_elements(p_randuri) x;
 IF cardinality(v_ids)<>(SELECT count(DISTINCT x) FROM unnest(v_ids) x) OR array_position(v_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'randuri_invalide'; END IF;
 -- Conservative project closure, same session-before-declaration order as sync.
 PERFORM 1 FROM public.izo_preverificari WHERE proiect_id=v_s.proiect_id ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.izo_declaratii WHERE proiect_id=v_s.proiect_id ORDER BY id FOR UPDATE;
 SELECT * INTO v_s FROM public.izo_preverificari WHERE id=p_preverificare;
 v_payload:=jsonb_build_object('preverificare',p_preverificare,'randuri',p_randuri,'amprenta',p_amprenta,'decizii',p_decizii);
 v_hash:=encode(sha256(convert_to(v_payload::text,'UTF8')),'hex');
 SELECT * INTO v_old FROM public.izo_operatii WHERE autor_profile_id=public.fn_izo_uid() AND op_id=p_cheie;
 IF FOUND THEN
  IF v_old.canal<>'aprobare' OR v_old.tip_op<>'aproba' OR v_old.hash_cerere<>v_hash THEN RAISE EXCEPTION 'cheie_refolosita'; END IF;
  PERFORM public.fn_izo_birou_autorizat(v_s.proiect_id,NULL,true);
  RETURN v_old.raspuns;
 END IF;
 v_emp:=public.fn_izo_birou_autorizat(v_s.proiect_id,NULL,true);
 IF v_s.stare<>'trimisa' THEN RAISE EXCEPTION 'sesiune_stare'; END IF;
 PERFORM public.fn_izo_blocheaza_locuri(v_s.proiect_id,ARRAY(SELECT DISTINCT coalesce(c.depozit_destinatie_id,(b.atribute->>'depozit_origine_id')::integer)
  FROM public.izo_bucati_declarate c JOIN public.magazie_bucati b ON b.id=c.radacina_id
  WHERE c.declaratie_id=ANY(v_ids) AND c.destinatie='depozit' AND coalesce(c.depozit_destinatie_id,(b.atribute->>'depozit_origine_id')::integer) IS NOT NULL ORDER BY 1),ARRAY[v_s.tronson_id]);
 PERFORM public.fn_izo_blocheaza_tabele(); PERFORM public.fn_izo_lock_partajat(v_s.proiect_id);
 IF coalesce(public.fn_izo_nivel(v_s.proiect_id),'off') NOT IN ('stoc','montaj') OR NOT EXISTS
  (SELECT 1 FROM public.izo_tronson_config WHERE tronson_id=v_s.tronson_id AND flux_montaj) THEN RAISE EXCEPTION 'flux_inactiv'; END IF;
 PERFORM 1 FROM public.magazie_bucati WHERE proiect_id=v_s.proiect_id AND id=radacina_id ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.magazie_bucati WHERE proiect_id=v_s.proiect_id ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.izo_suduri WHERE proiect_id=v_s.proiect_id ORDER BY id FOR UPDATE;
 v_doc:=public.fn_izo_birou_preview(v_s.id);
 IF encode(sha256(convert_to(v_doc::text,'UTF8')),'hex') IS DISTINCT FROM p_amprenta THEN RAISE EXCEPTION 'preview_vechi'; END IF;
 -- Validate every selected row before the first fact. Partial approval is an explicit subset.
 FOR v_r IN SELECT value FROM jsonb_array_elements(p_randuri) LOOP
  SELECT * INTO v_d FROM public.izo_declaratii WHERE id=(v_r->>'declaratie_id')::bigint AND proiect_id=v_s.proiect_id AND tronson_id=v_s.tronson_id
   AND preverificare_id IN (SELECT s.id FROM public.izo_preverificari s WHERE s.zi=v_s.zi AND s.stare='trimisa');
  IF NOT FOUND OR v_d.versiune IS DISTINCT FROM (v_r->>'versiune')::integer
   OR v_d.updated_at IS DISTINCT FROM (v_r->>'updated_at')::timestamptz OR v_d.stare<>'trimisa' THEN RAISE EXCEPTION 'cas'; END IF;
  IF v_d.declarat_de=public.fn_izo_uid() OR v_d.declarat_de_angajat=v_emp THEN RAISE EXCEPTION 'propriul_rand' USING ERRCODE='42501'; END IF;
 END LOOP;
 -- No registry DML precedes the complete simulation.
 v_plan:=public.fn_izo_lot_efecte(v_ids);
 SELECT coalesce(array_agg('corectie:'||d.id ORDER BY 'corectie:'||d.id),'{}') INTO v_keys FROM public.izo_declaratii d
  WHERE d.id=ANY(v_ids) AND public.fn_izo_corectie_mm(d.id) IS NOT NULL;
 SELECT coalesce(array_agg(k ORDER BY k),'{}') INTO v_given FROM jsonb_object_keys(p_decizii) k;
 IF v_keys IS DISTINCT FROM v_given OR EXISTS(SELECT 1 FROM jsonb_each(p_decizii) x WHERE jsonb_typeof(x.value)<>'string')
  OR EXISTS(SELECT 1 FROM jsonb_each_text(p_decizii) x WHERE length(btrim(coalesce(x.value,''))) NOT BETWEEN 3 AND 1000) THEN RAISE EXCEPTION 'decizii_invalide'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]') INTO v_rez_before FROM public.izo_rezervari r
  JOIN public.izo_bucati_declarate c ON c.uid=r.bucata_decl_uid WHERE c.declaratie_id=ANY(v_ids) AND r.activa;
 FOR v_id IN SELECT value::bigint FROM jsonb_array_elements_text(v_plan->'ordine') LOOP
  SELECT * INTO STRICT v_d FROM public.izo_declaratii WHERE id=v_id;
  IF v_d.tip<>'cuplare' THEN
  SELECT * INTO STRICT v_b FROM public.magazie_bucati WHERE id=coalesce(v_d.bucata_id,v_d.sursa_bucata_id)
   OR uid=coalesce(v_d.bucata_decl_uid,v_d.sursa_decl_uid);
  v_corr:=NULL; v_mm:=public.fn_izo_corectie_mm(v_d.id);
  IF v_mm IS NOT NULL THEN
   v_corr:=public.fn_izo_corectie_fapt(v_b.id,v_d.id::text,v_d.tronson_id,v_d.declarat_de,v_d.dispozitiv_id::text,p_decizii->>('corectie:'||v_d.id),v_mm);
   v_evs:=array_append(v_evs,v_corr);
  END IF;
  IF v_d.tip='taiere' THEN v_ev:=public.fn_izo_taiere_fapt(v_d.id);
  ELSE
  v_ev:=public.fn_izo_birou_fapt(v_b.id,'aproba',v_d.id::text,v_s.tronson_id,NULL,v_d.declarat_de,v_d.dispozitiv_id::text,
   (SELECT ora_tableta FROM public.izo_operatii WHERE autor_profile_id=v_d.declarat_de AND op_id=v_d.ultimul_op_id AND canal='teren'),NULL);
  END IF;
  v_evs:=array_append(v_evs,v_ev);
  UPDATE public.izo_rezervari SET activa=false,eliberata_la=clock_timestamp(),motiv_eliberare='consumata',eveniment_id=v_ev,
   server_ver=nextval('public.izo_server_ver_seq') WHERE declaratie_id=v_d.id AND declaratie_versiune=v_d.versiune AND bucata_id=v_b.id AND activa;
  GET DIAGNOSTICS v_n=ROW_COUNT; IF v_n<>1 THEN RAISE EXCEPTION 'reconciliere_rezervare'; END IF;
  END IF;
  PERFORM public.fn_izo_sudura_aproba(v_d.id);
  UPDATE public.izo_declaratii SET stare='aprobata',aprobat_de=public.fn_izo_uid(),aprobat_de_angajat=v_emp,
   decis_la=clock_timestamp(),eveniment_ids=CASE WHEN v_d.tip='cuplare' THEN '{}'::bigint[] ELSE CASE WHEN v_corr IS NULL THEN ARRAY[v_ev] ELSE ARRAY[v_ev,v_corr] END END,server_ver=nextval('public.izo_server_ver_seq') WHERE id=v_d.id;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.izo_suduri w WHERE w.proiect_id=v_s.proiect_id AND w.stare='aprobata'
  AND (SELECT count(*) FROM public.izo_suduri_capete c WHERE c.sudura_id=w.id AND c.activ)<>2)
  OR EXISTS(SELECT 1 FROM public.izo_suduri_capete c JOIN public.magazie_bucati b ON b.id=c.bucata_id
   WHERE b.proiect_id=v_s.proiect_id AND b.stare='taiata' AND c.activ) THEN RAISE EXCEPTION 'reconciliere_r4'; END IF;
 FOR v_expected IN SELECT key,value FROM jsonb_each(v_plan->'capete') LOOP
  IF v_expected.value->>'stare_sudura'='aprobata' AND NOT EXISTS(SELECT 1 FROM public.izo_suduri_capete c
   JOIN public.magazie_bucati b ON b.id=c.bucata_id WHERE c.sudura_id=(v_expected.value->>'sudura_id')::bigint
    AND c.parte=v_expected.value->>'parte' AND c.activ AND b.uid=(v_expected.value->>'uid')::uuid
    AND c.capat_litera=v_expected.value->>'capat_litera' AND b.stare='montata') THEN RAISE EXCEPTION 'reconciliere_r4'; END IF;
 END LOOP;
 FOR v_expected IN SELECT key,value FROM jsonb_each(v_plan->'bucati') LOOP
  SELECT * INTO STRICT v_b FROM public.magazie_bucati WHERE uid=v_expected.key::uuid;
  IF v_b.stare IS DISTINCT FROM v_expected.value->>'stare'
   OR v_b.lungime_mm IS DISTINCT FROM (v_expected.value->>'lungime_mm')::integer
   OR v_b.proiect_id IS DISTINCT FROM (v_expected.value->>'proiect_id')::bigint
   OR v_b.tronson_id IS DISTINCT FROM (v_expected.value->>'tronson_id')::bigint THEN RAISE EXCEPTION 'reconciliere_simulare'; END IF;
 END LOOP;
 -- Reconcile the complete reservation transfer chain, including consumers outside this lot.
 FOR v_r IN SELECT value FROM jsonb_array_elements(v_rez_before) LOOP
  SELECT * INTO STRICT v_res FROM public.izo_rezervari WHERE id=(v_r->>'id')::bigint;
  IF EXISTS(SELECT 1 FROM public.izo_bucati_declarate c WHERE c.uid=v_res.bucata_decl_uid AND c.destinatie='ramane_montat' AND c.declaratie_id=v_res.declaratie_id) THEN
   IF v_res.activa OR v_res.motiv_eliberare IS DISTINCT FROM 'consumata' OR v_res.eveniment_id IS DISTINCT FROM
    (SELECT d.eveniment_ids[1] FROM public.izo_declaratii d WHERE d.id=v_res.declaratie_id) THEN RAISE EXCEPTION 'reconciliere_transfer'; END IF;
   CONTINUE;
  END IF;
  IF v_res.activa OR v_res.motiv_eliberare IS DISTINCT FROM 'transferata'
   OR (to_jsonb(v_res)-ARRAY['activa','eliberata_la','motiv_eliberare','eveniment_id','server_ver'])
     IS DISTINCT FROM (v_r-ARRAY['activa','eliberata_la','motiv_eliberare','eveniment_id','server_ver'])
   OR v_res.eveniment_id IS DISTINCT FROM (SELECT d.eveniment_ids[1] FROM public.izo_bucati_declarate c
     JOIN public.izo_declaratii d ON d.id=c.declaratie_id WHERE c.uid=v_res.bucata_decl_uid) THEN RAISE EXCEPTION 'reconciliere_transfer'; END IF;
 END LOOP;
 FOR v_child IN SELECT * FROM public.izo_bucati_declarate WHERE declaratie_id=ANY(v_ids) AND stare='aprobata' LOOP
  IF EXISTS(SELECT 1 FROM public.izo_rezervari WHERE bucata_decl_uid=v_child.uid AND activa) THEN RAISE EXCEPTION 'reconciliere_transfer'; END IF;
  FOR v_res IN SELECT * FROM public.izo_rezervari WHERE bucata_decl_uid=v_child.uid AND motiv_eliberare='transferata' LOOP
   IF (SELECT count(*) FROM public.izo_rezervari r WHERE r.transfer_din_id=v_res.id AND r.bucata_id=v_child.bucata_id
    AND r.declaratie_id=v_res.declaratie_id AND r.declaratie_versiune=v_res.declaratie_versiune
    AND r.autor_profile_id=v_res.autor_profile_id AND r.expira_dupa IS NOT DISTINCT FROM v_res.expira_dupa
    AND (CASE WHEN r.declaratie_id=ANY(v_ids) THEN NOT r.activa AND r.motiv_eliberare='consumata'
     AND r.eveniment_id=(SELECT d.eveniment_ids[1] FROM public.izo_declaratii d WHERE d.id=r.declaratie_id) ELSE r.activa END))<>1
    THEN RAISE EXCEPTION 'reconciliere_transfer'; END IF;
  END LOOP;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.izo_rezervari WHERE declaratie_id=ANY(v_ids) AND activa) THEN RAISE EXCEPTION 'reconciliere_rezervare'; END IF;
 IF EXISTS(SELECT 1 FROM public.magazie_bucati root WHERE root.proiect_id=v_s.proiect_id AND root.id=root.radacina_id
  AND root.lungime_mm IS DISTINCT FROM (SELECT sum(b.lungime_mm)::integer FROM public.magazie_bucati b
   WHERE b.radacina_id=root.id AND b.stare NOT IN ('taiata','anulata'))) THEN RAISE EXCEPTION 'r3'; END IF;
 UPDATE public.izo_preverificari s SET stare='inchisa',server_ver=nextval('public.izo_server_ver_seq')
 WHERE s.id IN (SELECT d.preverificare_id FROM public.izo_declaratii d WHERE d.id=ANY(v_ids))
 AND NOT EXISTS(SELECT 1 FROM public.izo_declaratii d WHERE d.preverificare_id=s.id AND d.stare NOT IN ('aprobata','respinsa','stearsa')); 
 v_r:=jsonb_build_object('cod','aprobat','eveniment_ids',to_jsonb(v_evs),
  'bucati_noi',(SELECT coalesce(jsonb_object_agg(c.uid,c.bucata_id),'{}') FROM public.izo_bucati_declarate c WHERE c.declaratie_id=ANY(v_ids) AND c.stare='aprobata'),
  'fise_taiere_radacini',(SELECT coalesce(jsonb_agg(x.radacina_id ORDER BY x.radacina_id),'[]') FROM
   (SELECT DISTINCT c.radacina_id FROM public.izo_bucati_declarate c WHERE c.declaratie_id=ANY(v_ids) AND c.stare='aprobata') x));
 INSERT INTO public.izo_aprobari(cheie_operatie,proiect_id,tronson_id,aprobator,aprobator_angajat,randuri,decizii,hash_cerere,amprenta_preview,eveniment_ids,raspuns)
 VALUES(p_cheie,v_s.proiect_id,v_s.tronson_id,public.fn_izo_uid(),v_emp,p_randuri,p_decizii,v_hash,p_amprenta,v_evs,v_r);
 PERFORM public.fn_izo_birou_jurnal(p_cheie,'aprobare','aproba',v_s.proiect_id,v_s.tronson_id,v_payload,v_hash,v_r);
 RETURN v_r;
END $f$;

  CREATE FUNCTION public.fn_izo_aprobare_lot(p_preverificare bigint) RETURNS jsonb
 LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 SELECT public.fn_izo_aprobare_intern(p_preverificare)
$f$;
  CREATE FUNCTION public.fn_izo_aproba(p_cheie uuid,p_preverificare bigint,p_randuri jsonb,p_amprenta text,p_decizii jsonb) RETURNS jsonb
 LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 SELECT public.fn_izo_aproba_intern(p_cheie,p_preverificare,p_randuri,p_amprenta,p_decizii)
$f$;

  CREATE FUNCTION public.fn_izo_iesire_intern(p_cheie uuid,p_depozit integer,p_tronson bigint,p_bucati bigint[],p_nr_aviz text,p_data date) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_pr bigint; v_b public.magazie_bucati; v_payload jsonb; v_hash text; v_old public.izo_operatii;
 v_r jsonb; v_evs bigint[]:='{}'; v_ev bigint; v_ids bigint[]; v_site integer;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ COMMITTED' USING ERRCODE='25001'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
 SELECT proiect_id INTO v_pr FROM public.executie_tronsoane WHERE id=p_tronson;
 PERFORM public.fn_izo_birou_intrare(v_pr,p_depozit);
 IF v_pr IS NULL THEN RAISE EXCEPTION 'tronson_lipsa'; END IF;
 IF p_cheie IS NULL OR p_depozit IS NULL OR p_data IS NULL OR p_data>current_date
  OR length(btrim(coalesce(p_nr_aviz,''))) NOT BETWEEN 3 AND 100 OR cardinality(p_bucati) NOT BETWEEN 1 AND 200
  OR p_bucati IS NULL OR array_position(p_bucati,NULL) IS NOT NULL THEN RAISE EXCEPTION 'parametri_invalizi'; END IF;
 SELECT array_agg(x ORDER BY x) INTO v_ids FROM unnest(p_bucati) x;
 IF cardinality(v_ids)<>(SELECT count(DISTINCT x) FROM unnest(v_ids) x) THEN RAISE EXCEPTION 'bucati_duplicate'; END IF;
 -- Serialize a depot key without taking root locks before authorization/locations.
 PERFORM pg_advisory_xact_lock(hashtextextended('izo.iesire|'||public.fn_izo_uid()::text||'|'||p_cheie::text,0));
 v_payload:=jsonb_build_object('depozit',p_depozit,'tronson',p_tronson,'bucati',to_jsonb(v_ids),'nr_aviz',btrim(p_nr_aviz),'data',p_data);
 v_hash:=encode(sha256(convert_to(v_payload::text,'UTF8')),'hex');
 SELECT * INTO v_old FROM public.izo_operatii WHERE autor_profile_id=public.fn_izo_uid() AND op_id=p_cheie;
 PERFORM public.fn_izo_birou_autorizat(v_pr,p_depozit,true);
 IF v_old.id IS NOT NULL THEN
  IF v_old.canal<>'depozit' OR v_old.tip_op<>'iesire' OR v_old.hash_cerere<>v_hash THEN RAISE EXCEPTION 'cheie_refolosita'; END IF;
  RETURN v_old.raspuns;
 END IF;
 PERFORM public.fn_izo_blocheaza_locuri(v_pr,ARRAY[p_depozit],ARRAY[p_tronson]);
 PERFORM public.fn_izo_blocheaza_tabele(); PERFORM public.fn_izo_lock_partajat(v_pr);
 IF coalesce(public.fn_izo_nivel(v_pr),'off') NOT IN ('stoc','montaj') OR NOT EXISTS
  (SELECT 1 FROM public.izo_tronson_config WHERE tronson_id=p_tronson AND flux_montaj) THEN RAISE EXCEPTION 'flux_inactiv'; END IF;
 SELECT site_id INTO v_site FROM public.executie_proiecte WHERE id=v_pr;
 IF NOT EXISTS(SELECT 1 FROM public.logistica_depozite WHERE id=p_depozit AND activ AND site_id=v_site) THEN RAISE EXCEPTION 'depozit_invalid'; END IF;
 PERFORM 1 FROM public.magazie_bucati WHERE id IN (SELECT coalesce(radacina_id,id) FROM public.magazie_bucati WHERE id=ANY(v_ids)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.magazie_bucati WHERE id=ANY(v_ids) ORDER BY id FOR UPDATE;
 IF (SELECT count(*) FROM public.magazie_bucati WHERE id=ANY(v_ids))<>cardinality(v_ids) THEN RAISE EXCEPTION 'bucata_lipsa'; END IF;
 FOR v_b IN SELECT * FROM public.magazie_bucati WHERE id=ANY(v_ids) ORDER BY id LOOP
  IF v_b.proiect_id IS DISTINCT FROM v_pr OR v_b.tip_cod IS NULL OR v_b.provenienta<>'beneficiar'
   OR v_b.stare NOT IN ('sosit','receptionat','retur') OR v_b.depozit_id IS DISTINCT FROM p_depozit
   OR v_b.executie_teava_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.magazie_bucati WHERE parinte_id=v_b.id AND stare<>'anulata') THEN RAISE EXCEPTION 'stare'; END IF;
  IF cardinality(public.fn_izo_pv_lipsa(ARRAY[coalesce(v_b.radacina_id,v_b.id)]))>0 THEN RAISE EXCEPTION 'fara_pv'; END IF;
  -- A reservation on this tronson is regularized; one on another tronson is not.
  IF EXISTS(SELECT 1 FROM public.izo_rezervari WHERE bucata_id=v_b.id AND activa
    AND (expira_dupa IS NULL OR expira_dupa>now()) AND tronson_id<>p_tronson) THEN RAISE EXCEPTION 'rezervata_alt_tronson'; END IF;
 END LOOP;
 FOR v_b IN SELECT * FROM public.magazie_bucati WHERE id=ANY(v_ids) ORDER BY id LOOP
  v_ev:=public.fn_izo_birou_fapt(v_b.id,'iesire',p_cheie::text,p_tronson,p_depozit,public.fn_izo_uid(),NULL,
   p_data::timestamp AT TIME ZONE 'Europe/Bucharest','Aviz '||btrim(p_nr_aviz));
  v_evs:=array_append(v_evs,v_ev);
 END LOOP;
 v_r:=jsonb_build_object('cod','iesit','eveniment_ids',to_jsonb(v_evs));
 PERFORM public.fn_izo_birou_jurnal(p_cheie,'depozit','iesire',v_pr,p_tronson,v_payload,v_hash,v_r);
 RETURN v_r;
END $f$;

  CREATE FUNCTION public.fn_izo_dependenti(p_decl bigint) RETURNS bigint[]
 LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 WITH RECURSIVE deps AS (
  SELECT id,uid FROM public.izo_declaratii WHERE id=p_decl
  UNION
  SELECT d.id,d.uid FROM public.izo_declaratii d JOIN deps x ON d.depinde_de_uid=x.uid
   OR EXISTS(SELECT 1 FROM public.izo_bucati_declarate c WHERE c.declaratie_id=x.id AND c.uid IN (d.bucata_decl_uid,d.sursa_decl_uid))
  WHERE d.stare NOT IN ('aprobata','respinsa','stearsa')
 ) SELECT coalesce(array_agg(id ORDER BY id),'{}'::bigint[]) FROM deps
$f$;

  CREATE FUNCTION public.fn_izo_decizie_intern(p_cheie uuid,p_decl bigint,p_versiune integer,p_updated_at timestamptz,
 p_motiv text,p_dependente jsonb,p_revizie boolean) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_d public.izo_declaratii; v_x public.izo_declaratii; v_s public.izo_preverificari;
 v_ids bigint[]; v_before bigint[]; v_keys text[]; v_actual text[]; v_choice text; v_hash text; v_payload jsonb; v_r jsonb;
 v_old public.izo_operatii; v_type text:=CASE WHEN p_revizie THEN 'revizie' ELSE 'respinge' END;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ COMMITTED' USING ERRCODE='25001'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
 SELECT * INTO v_d FROM public.izo_declaratii WHERE id=p_decl;
 PERFORM public.fn_izo_birou_intrare(v_d.proiect_id,NULL);
 IF v_d.id IS NULL THEN RAISE EXCEPTION 'declaratie_lipsa'; END IF;
 IF p_cheie IS NULL OR p_updated_at IS NULL OR length(btrim(coalesce(p_motiv,''))) NOT BETWEEN 3 AND 1000
  OR p_revizie IS NULL OR jsonb_typeof(p_dependente) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parametri_invalizi'; END IF;
 PERFORM 1 FROM public.izo_fronturi WHERE proiect_id=v_d.proiect_id ORDER BY id FOR SHARE;
 v_before:=public.fn_izo_dependenti(p_decl);
 -- Conservative project closure, acquired once in the same order as sync.
 PERFORM 1 FROM public.izo_preverificari WHERE proiect_id=v_d.proiect_id ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.izo_declaratii WHERE proiect_id=v_d.proiect_id ORDER BY id FOR UPDATE;
 v_ids:=public.fn_izo_dependenti(p_decl);
 IF v_before IS DISTINCT FROM v_ids THEN RAISE EXCEPTION 'preview_vechi'; END IF;
 SELECT * INTO v_d FROM public.izo_declaratii WHERE id=p_decl;
 v_payload:=jsonb_build_object('decl',p_decl,'versiune',p_versiune,'updated_at',p_updated_at,'motiv',btrim(p_motiv),'dependente',p_dependente,'revizie',p_revizie);
 v_hash:=encode(sha256(convert_to(v_payload::text,'UTF8')),'hex');
 SELECT * INTO v_old FROM public.izo_operatii WHERE autor_profile_id=public.fn_izo_uid() AND op_id=p_cheie;
 PERFORM public.fn_izo_birou_autorizat(v_d.proiect_id,NULL,true);
 IF v_old.id IS NOT NULL THEN
  IF v_old.canal<>'aprobare' OR v_old.tip_op<>v_type OR v_old.hash_cerere<>v_hash THEN RAISE EXCEPTION 'cheie_refolosita'; END IF;
  RETURN v_old.raspuns;
 END IF;
 IF v_d.versiune IS DISTINCT FROM p_versiune OR v_d.updated_at IS DISTINCT FROM p_updated_at THEN RAISE EXCEPTION 'cas'; END IF;
 PERFORM public.fn_izo_autor_valabil(declarat_de,proiect_id,true) FROM public.izo_declaratii WHERE id=ANY(v_ids) ORDER BY declarat_de;
 SELECT * INTO v_s FROM public.izo_preverificari WHERE id=v_d.preverificare_id;
 IF p_revizie THEN
  IF v_s.stare<>'trimisa' OR v_d.stare NOT IN ('trimisa','in_verificare') OR p_dependente<>'{}'::jsonb THEN RAISE EXCEPTION 'stare'; END IF;
 ELSE
  IF v_d.stare IN ('aprobata','respinsa','stearsa') OR (v_s.stare='deschisa' AND EXISTS(
   SELECT 1 FROM public.izo_fronturi WHERE tronson_id=v_s.tronson_id AND profile_id=v_s.autor_profile_id AND activ AND expira_la>now())
    AND public.fn_izo_autor_valabil(v_s.autor_profile_id,v_s.proiect_id,false)) THEN RAISE EXCEPTION 'stare'; END IF;
  SELECT coalesce(array_agg(x::text ORDER BY x::text),'{}') INTO v_keys FROM unnest(v_ids) x WHERE x<>p_decl;
  SELECT coalesce(array_agg(x ORDER BY x),'{}') INTO v_actual FROM jsonb_object_keys(p_dependente) x;
  IF v_keys IS DISTINCT FROM v_actual THEN RAISE EXCEPTION 'dependente_schimbate'; END IF;
 END IF;
 PERFORM 1 FROM public.magazie_bucati WHERE proiect_id=v_d.proiect_id AND id=radacina_id ORDER BY id FOR UPDATE;
 FOR v_x IN SELECT * FROM public.izo_declaratii WHERE id=ANY(v_ids) ORDER BY id LOOP
  IF v_x.id=p_decl THEN
   UPDATE public.izo_declaratii SET stare=CASE WHEN p_revizie THEN 'revizie_ceruta' ELSE 'respinsa' END,
    stare_inainte_blocare=NULL,blocata_motiv=NULL,conflict_cod=NULL,decis_la=clock_timestamp(),decizie_motiv=btrim(p_motiv),
    server_ver=nextval('public.izo_server_ver_seq') WHERE id=v_x.id;
  ELSE
   v_choice:=CASE WHEN p_revizie THEN 'blocheaza' ELSE p_dependente->>v_x.id::text END;
   IF v_choice IS NULL OR v_choice NOT IN ('blocheaza','respinge') THEN RAISE EXCEPTION 'decizie_nepermisa'; END IF;
   IF v_choice='respinge' AND EXISTS(SELECT 1 FROM public.izo_preverificari s JOIN public.izo_fronturi f
    ON f.tronson_id=s.tronson_id AND f.profile_id=s.autor_profile_id
    WHERE s.id=v_x.preverificare_id AND s.stare='deschisa' AND f.activ AND f.expira_la>now()
     AND public.fn_izo_autor_valabil(s.autor_profile_id,s.proiect_id,false)) THEN RAISE EXCEPTION 'decizie_nepermisa'; END IF;
   UPDATE public.izo_declaratii SET stare=CASE WHEN v_choice='respinge' THEN 'respinsa' ELSE 'blocata' END,
    stare_inainte_blocare=CASE WHEN v_choice='blocheaza' THEN coalesce(v_x.stare_inainte_blocare,v_x.stare) END,
    blocata_motiv=CASE WHEN v_choice='blocheaza' THEN CASE WHEN NOT p_revizie OR v_x.blocata_motiv='dependenta_anulata' THEN 'dependenta_anulata' ELSE 'dependenta_in_revizie' END END,
    conflict_cod=CASE WHEN v_choice='blocheaza' THEN v_x.conflict_cod END,
    decis_la=clock_timestamp(),decizie_motiv=btrim(p_motiv),server_ver=nextval('public.izo_server_ver_seq') WHERE id=v_x.id;
  END IF;
 END LOOP;
 IF NOT p_revizie THEN
  UPDATE public.izo_suduri_capete c SET activ=false,server_ver=nextval('public.izo_server_ver_seq') WHERE c.activ AND c.sudura_id IN (SELECT s.id FROM public.izo_suduri s JOIN public.izo_declaratii d ON d.id=s.declaratie_id WHERE d.id=ANY(v_ids) AND d.stare='respinsa' AND s.stare='declarata');
  UPDATE public.izo_suduri s SET stare='anulata',server_ver=nextval('public.izo_server_ver_seq') WHERE s.declaratie_id IN (SELECT d.id FROM public.izo_declaratii d WHERE d.id=ANY(v_ids) AND d.stare='respinsa') AND s.stare='declarata';
  UPDATE public.izo_rezervari SET activa=false,eliberata_la=clock_timestamp(),motiv_eliberare=CASE WHEN declaratie_id=p_decl THEN 'respinsa' ELSE 'parinte_anulat' END,
   server_ver=nextval('public.izo_server_ver_seq') WHERE activa AND (declaratie_id=ANY(v_ids) OR bucata_decl_uid IN
    (SELECT uid FROM public.izo_bucati_declarate WHERE declaratie_id=ANY(v_ids)));
  UPDATE public.izo_bucati_declarate SET stare='anulata',server_ver=nextval('public.izo_server_ver_seq') WHERE declaratie_id=ANY(v_ids) AND stare='declarata';
 END IF;
 UPDATE public.izo_preverificari s SET stare='inchisa',server_ver=nextval('public.izo_server_ver_seq')
 WHERE s.id IN (SELECT preverificare_id FROM public.izo_declaratii WHERE id=ANY(v_ids)) AND s.stare<>'inchisa'
  AND NOT EXISTS(SELECT 1 FROM public.izo_declaratii d WHERE d.preverificare_id=s.id AND d.stare NOT IN ('aprobata','respinsa','stearsa'));
 v_r:=jsonb_build_object('cod',CASE WHEN p_revizie THEN 'revizie_ceruta' ELSE 'respinsa' END,'declaratie_id',p_decl);
 PERFORM public.fn_izo_birou_jurnal(p_cheie,'aprobare',v_type,v_d.proiect_id,v_d.tronson_id,v_payload,v_hash,v_r);
 RETURN v_r;
END $f$;

  CREATE FUNCTION public.fn_izo_front_intern(p_tronson bigint,p_motiv text) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_pr bigint; v_n bigint;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ COMMITTED' USING ERRCODE='25001'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
 SELECT proiect_id INTO v_pr FROM public.executie_tronsoane WHERE id=p_tronson;
 PERFORM public.fn_izo_birou_intrare(v_pr,NULL);
 IF v_pr IS NULL THEN RAISE EXCEPTION 'tronson_lipsa'; END IF;
 IF length(btrim(coalesce(p_motiv,''))) NOT BETWEEN 3 AND 1000 THEN RAISE EXCEPTION 'motiv_obligatoriu'; END IF;
 PERFORM 1 FROM public.izo_fronturi WHERE tronson_id=p_tronson AND activ FOR UPDATE;
 PERFORM public.fn_izo_birou_autorizat(v_pr,NULL,true);
 UPDATE public.izo_fronturi SET activ=false,eliberat_de=public.fn_izo_uid(),eliberat_motiv=btrim(p_motiv),
  server_ver=nextval('public.izo_server_ver_seq') WHERE tronson_id=p_tronson AND activ;
 GET DIAGNOSTICS v_n=ROW_COUNT;
 RETURN jsonb_build_object('cod',CASE WHEN v_n=0 THEN 'fara_efect' ELSE 'eliberat' END);
END $f$;

  CREATE FUNCTION public.fn_izo_iesire_tronson(p_cheie uuid,p_depozit integer,p_tronson bigint,p_bucati bigint[],p_nr_aviz text,p_data date) RETURNS jsonb
 LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 SELECT public.fn_izo_iesire_intern(p_cheie,p_depozit,p_tronson,p_bucati,p_nr_aviz,p_data)
$f$;
  CREATE FUNCTION public.fn_izo_respinge(p_cheie uuid,p_decl bigint,p_versiune integer,p_updated_at timestamptz,p_motiv text,p_dependente jsonb) RETURNS jsonb
 LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 SELECT public.fn_izo_decizie_intern(p_cheie,p_decl,p_versiune,p_updated_at,p_motiv,p_dependente,false)
$f$;
  CREATE FUNCTION public.fn_izo_revizie_cere(p_cheie uuid,p_decl bigint,p_versiune integer,p_updated_at timestamptz,p_motiv text) RETURNS jsonb
 LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 SELECT public.fn_izo_decizie_intern(p_cheie,p_decl,p_versiune,p_updated_at,p_motiv,'{}'::jsonb,true)
$f$;
  CREATE FUNCTION public.fn_izo_front_elibereaza(p_tronson bigint,p_motiv text) RETURNS jsonb
 LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 SELECT public.fn_izo_front_intern(p_tronson,p_motiv)
$f$;

  CREATE FUNCTION public.fn_izo_serie_intern(p_cheie uuid,p_decl bigint,p_versiune integer,p_updated_at timestamptz,p_bucata bigint,p_motiv text) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_d public.izo_declaratii; v_b public.magazie_bucati; v_s public.izo_preverificari;
 v_payload jsonb; v_hash text; v_old public.izo_operatii; v_r jsonb; v_conflict text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ COMMITTED' USING ERRCODE='25001'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
 SELECT * INTO v_d FROM public.izo_declaratii WHERE id=p_decl;
 PERFORM public.fn_izo_birou_intrare(v_d.proiect_id,NULL);
 IF v_d.id IS NULL OR p_cheie IS NULL OR p_updated_at IS NULL OR p_bucata IS NULL
  OR length(btrim(coalesce(p_motiv,''))) NOT BETWEEN 3 AND 1000 THEN RAISE EXCEPTION 'parametri_invalizi'; END IF;
 SELECT * INTO v_s FROM public.izo_preverificari WHERE id=v_d.preverificare_id FOR UPDATE;
 SELECT * INTO v_d FROM public.izo_declaratii WHERE id=p_decl FOR UPDATE;
 v_payload:=jsonb_build_object('decl',p_decl,'versiune',p_versiune,'updated_at',p_updated_at,'bucata',p_bucata,'motiv',btrim(p_motiv));
 v_hash:=encode(sha256(convert_to(v_payload::text,'UTF8')),'hex');
 SELECT * INTO v_old FROM public.izo_operatii WHERE autor_profile_id=public.fn_izo_uid() AND op_id=p_cheie;
 PERFORM public.fn_izo_birou_autorizat(v_d.proiect_id,NULL,true);
 IF v_old.id IS NOT NULL THEN
  IF v_old.canal<>'aprobare' OR v_old.tip_op<>'serie' OR v_old.hash_cerere<>v_hash THEN RAISE EXCEPTION 'cheie_refolosita'; END IF;
  RETURN v_old.raspuns;
 END IF;
 IF v_s.stare<>'trimisa' OR v_d.stare<>'in_verificare' OR v_d.identificare IS DISTINCT FROM 'nerezolvata'
  OR v_d.versiune IS DISTINCT FROM p_versiune OR v_d.updated_at IS DISTINCT FROM p_updated_at THEN RAISE EXCEPTION 'cas'; END IF;
 PERFORM public.fn_izo_blocheaza_locuri(v_d.proiect_id,ARRAY[]::integer[],ARRAY[v_d.tronson_id]);
 PERFORM 1 FROM public.izo_tronson_config WHERE tronson_id=v_d.tronson_id FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM public.izo_tronson_config WHERE tronson_id=v_d.tronson_id AND flux_montaj)
  OR coalesce(public.fn_izo_nivel(v_d.proiect_id),'off')='off' THEN RAISE EXCEPTION 'flux_inactiv'; END IF;
 PERFORM 1 FROM public.magazie_bucati WHERE proiect_id=v_d.proiect_id AND id=radacina_id ORDER BY id FOR UPDATE;
 SELECT * INTO v_b FROM public.magazie_bucati WHERE id=p_bucata FOR UPDATE;
 IF NOT FOUND OR v_b.proiect_id IS DISTINCT FROM v_d.proiect_id OR v_b.stare IS DISTINCT FROM 'pe_tronson'
  OR v_b.tronson_id IS DISTINCT FROM v_d.tronson_id OR v_b.tip_cod IS NULL OR v_b.executie_teava_id IS NOT NULL
  OR EXISTS(SELECT 1 FROM public.magazie_bucati WHERE parinte_id=v_b.id AND stare<>'anulata') THEN RAISE EXCEPTION 'stare'; END IF;
 IF v_b.lungime_mm IS DISTINCT FROM (v_d.payload->>'lungime_montata_mm')::integer THEN RAISE EXCEPTION 'lungime_incompatibila'; END IF;
 IF cardinality(public.fn_izo_pv_lipsa(ARRAY[coalesce(v_b.radacina_id,v_b.id)]))>0 THEN RAISE EXCEPTION 'fara_pv'; END IF;
 IF EXISTS(SELECT 1 FROM public.izo_rezervari WHERE bucata_id=v_b.id AND activa AND (expira_dupa IS NULL OR expira_dupa>now())) THEN RAISE EXCEPTION 'bucata_rezervata'; END IF;
 IF (SELECT count(*) FROM public.izo_rezervari WHERE autor_profile_id=v_d.declarat_de AND activa AND (expira_dupa IS NULL OR expira_dupa>now()))>=60 THEN RAISE EXCEPTION 'limita'; END IF;
 UPDATE public.izo_rezervari SET activa=false,eliberata_la=clock_timestamp(),motiv_eliberare='expirata',
  server_ver=nextval('public.izo_server_ver_seq') WHERE bucata_id=v_b.id AND activa AND expira_dupa<=now();
 IF EXISTS(SELECT 1 FROM public.magazie_bucati b WHERE b.id<>v_b.id AND b.proiect_id=v_b.proiect_id AND b.stare NOT IN ('taiata','anulata')
  AND b.serie_canon=v_b.serie_canon AND b.sarja IS NOT DISTINCT FROM v_b.sarja AND b.lungime_cm=v_b.lungime_cm
  AND NOT EXISTS(SELECT 1 FROM public.magazie_bucati c WHERE c.parinte_id=b.id AND c.stare<>'anulata')) THEN v_conflict:='r1d'; END IF;
 UPDATE public.izo_declaratii SET bucata_id=v_b.id,identificare='bucata',stare=CASE WHEN v_conflict IS NULL THEN 'trimisa' ELSE 'conflict' END,
  conflict_cod=v_conflict,versiune=versiune+1,decis_la=clock_timestamp(),decizie_motiv=btrim(p_motiv),
  payload=payload||jsonb_build_object('bucata',jsonb_build_object('bucata_id',v_b.id)),
  server_ver=nextval('public.izo_server_ver_seq') WHERE id=v_d.id RETURNING * INTO v_d;
 INSERT INTO public.izo_declaratii_versiuni(declaratie_id,versiune,payload,hash_cerere,op_id)
 VALUES(v_d.id,v_d.versiune,v_d.payload,v_hash,p_cheie);
 INSERT INTO public.izo_rezervari(proiect_id,tronson_id,declaratie_id,declaratie_versiune,autor_profile_id,bucata_id,din_depozit)
 VALUES(v_d.proiect_id,v_d.tronson_id,v_d.id,v_d.versiune,v_d.declarat_de,v_b.id,false);
 v_r:=jsonb_build_object('cod','lamurita','declaratie_id',v_d.id,'versiune',v_d.versiune,'updated_at',v_d.updated_at,'stare',v_d.stare);
 PERFORM public.fn_izo_birou_jurnal(p_cheie,'aprobare','serie',v_d.proiect_id,v_d.tronson_id,v_payload,v_hash,v_r);
 RETURN v_r;
END $f$;
  CREATE FUNCTION public.fn_izo_serie_lamureste(p_cheie uuid,p_decl bigint,p_versiune integer,p_updated_at timestamptz,p_bucata bigint,p_motiv text) RETURNS jsonb
 LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 SELECT public.fn_izo_serie_intern(p_cheie,p_decl,p_versiune,p_updated_at,p_bucata,p_motiv)
$f$;

-- E4b-2b: read-only topological simulation. Virtual children are keyed by uid;
-- no sequence, table or reservation is changed until every row has passed.
  CREATE FUNCTION public.fn_izo_lot_efecte(p_ids bigint[]) RETURNS jsonb
 LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_left bigint[]:=p_ids; v_done bigint[]:='{}'; v_order bigint[]:='{}';
 v_state jsonb:='{}'; v_d public.izo_declaratii; v_p public.izo_declaratii;
 v_b jsonb; v_c public.izo_bucati_declarate; v_uid uuid; v_root bigint;
 v_caps jsonb; v_cap record; v_cb jsonb; v_s public.izo_suduri; v_wait boolean; v_nc integer; v_target uuid;
 v_mm integer;
 v_progress boolean; v_sum bigint; v_count integer; v_dep bigint; v_res public.izo_rezervari; v_prev text;
BEGIN
 SELECT coalesce(jsonb_object_agg(c.id,to_jsonb(c)||jsonb_build_object('uid',coalesce(b.uid,c.bucata_decl_uid),'stare_sudura',s.stare)),'{}')
 INTO v_caps FROM public.izo_suduri_capete c JOIN public.izo_suduri s ON s.id=c.sudura_id
 LEFT JOIN public.magazie_bucati b ON b.id=c.bucata_id WHERE c.activ AND s.stare<>'anulata' AND s.proiect_id IN (SELECT d.proiect_id FROM public.izo_declaratii d WHERE d.id=ANY(p_ids));
 WHILE cardinality(v_left)>0 LOOP
  v_progress:=false;
  FOR v_d IN SELECT * FROM public.izo_declaratii WHERE id=ANY(v_left) ORDER BY id LOOP
   IF v_d.stare<>'trimisa' OR v_d.conflict_cod IS NOT NULL THEN RAISE EXCEPTION 'cas'; END IF;
   IF v_d.tip NOT IN ('taiere','montaj','cuplare') THEN RAISE EXCEPTION 'tip'; END IF;
   v_dep:=NULL;
   IF v_d.depinde_de_uid IS NOT NULL THEN
    SELECT * INTO v_p FROM public.izo_declaratii WHERE uid=v_d.depinde_de_uid;
    IF NOT FOUND OR v_p.versiune IS DISTINCT FROM v_d.depinde_de_versiune
     OR v_p.proiect_id<>v_d.proiect_id OR v_p.tronson_id<>v_d.tronson_id THEN RAISE EXCEPTION 'dependenta'; END IF;
    v_dep:=v_p.id;
    IF v_p.stare<>'aprobata' AND NOT v_p.id=ANY(v_done) THEN
     IF NOT v_p.id=ANY(p_ids) THEN RAISE EXCEPTION 'dependenta_lipsa'; END IF;
     CONTINUE;
    END IF;
   END IF;
   -- A weld waits for every endpoint's mount, including another session in this lot.
   SELECT * INTO v_s FROM public.izo_suduri WHERE declaratie_id=v_d.id AND stare='declarata';
   IF FOUND THEN
    v_wait:=false; v_nc:=0; v_target:=NULL;
    FOR v_cap IN SELECT key,value FROM jsonb_each(v_caps) WHERE (value->>'sudura_id')::bigint=v_s.id LOOP
     v_nc:=v_nc+1;
     IF v_target=(v_cap.value->>'uid')::uuid THEN RAISE EXCEPTION 'r4'; END IF;
     v_target:=(v_cap.value->>'uid')::uuid;
     v_cb:=v_state->(v_cap.value->>'uid');
     IF v_cb IS NULL THEN SELECT to_jsonb(b) INTO v_cb FROM public.magazie_bucati b WHERE b.uid=v_target; END IF;
     IF v_d.tip='montaj' AND (v_cb->>'id')::bigint=v_d.bucata_id OR v_d.tip='montaj' AND v_target=v_d.bucata_decl_uid THEN
      v_cb:=v_cb||'{"stare":"montata"}'::jsonb;
     END IF;
     IF v_cb IS NULL OR v_cb->>'stare'<>'montata' THEN
      IF EXISTS(SELECT 1 FROM public.izo_declaratii d LEFT JOIN public.magazie_bucati b ON b.id=d.bucata_id
       WHERE d.id=ANY(v_left) AND d.id<>v_d.id AND d.tip='montaj' AND coalesce(b.uid,d.bucata_decl_uid)=v_target) THEN
       v_wait:=true;
      ELSE RAISE EXCEPTION 'r4'; END IF;
     END IF;
     IF v_cb IS NOT NULL AND ((v_cb->>'proiect_id')::bigint IS DISTINCT FROM v_d.proiect_id
      OR (v_cb->>'tronson_id')::bigint IS DISTINCT FROM v_d.tronson_id
      OR v_cap.value->>'capat_litera' NOT IN (v_cb->>'capat_stanga',v_cb->>'capat_dreapta')) THEN RAISE EXCEPTION 'r4'; END IF;
    END LOOP;
    IF v_nc<>2 THEN RAISE EXCEPTION 'r4'; END IF;
    IF v_wait THEN CONTINUE; END IF;
   ELSIF v_d.payload ? 'sudura' OR v_d.tip='cuplare' THEN RAISE EXCEPTION 'r4'; END IF;
   IF v_d.tip<>'cuplare' THEN
   IF v_d.tip='montaj' AND v_d.identificare='nerezolvata' THEN RAISE EXCEPTION 'stare'; END IF;
   SELECT b.uid INTO v_uid FROM public.magazie_bucati b
    WHERE b.id=CASE WHEN v_d.tip='taiere' THEN v_d.sursa_bucata_id ELSE v_d.bucata_id END;
   v_uid:=coalesce(v_uid,CASE WHEN v_d.tip='taiere' THEN v_d.sursa_decl_uid ELSE v_d.bucata_decl_uid END);
   IF v_uid IS NULL THEN RAISE EXCEPTION 'stare'; END IF;
   v_b:=v_state->v_uid::text;
   IF v_b IS NULL THEN SELECT to_jsonb(b) INTO v_b FROM public.magazie_bucati b WHERE b.uid=v_uid; END IF;
   IF v_b IS NULL OR v_b->>'stare' NOT IN ('pe_tronson','montata') OR v_b->>'stare'='montata' AND v_d.tip<>'taiere' OR (v_b->>'tronson_id')::bigint IS DISTINCT FROM v_d.tronson_id
    OR (v_b->>'proiect_id')::bigint IS DISTINCT FROM v_d.proiect_id OR v_b->>'tip_cod' IS NULL
    THEN RAISE EXCEPTION 'stare'; END IF;
   IF v_b->>'executie_teava_id' IS NOT NULL THEN RAISE EXCEPTION 'bucata_in_pachet'; END IF;
   IF coalesce(v_d.sursa_decl_uid,v_d.bucata_decl_uid) IS NOT NULL THEN
    SELECT * INTO v_c FROM public.izo_bucati_declarate WHERE uid=v_uid;
    IF NOT FOUND OR v_c.declaratie_id IS DISTINCT FROM v_dep OR v_c.destinatie<>'montaj'
     OR v_c.stare NOT IN ('declarata','aprobata') THEN RAISE EXCEPTION 'dependenta'; END IF;
   END IF;
   v_root:=(v_b->>'radacina_id')::bigint;
   IF cardinality(public.fn_izo_pv_lipsa(ARRAY[v_root]))>0 THEN RAISE EXCEPTION 'fara_pv'; END IF;
   SELECT * INTO v_res FROM public.izo_rezervari r WHERE r.declaratie_id=v_d.id AND r.declaratie_versiune=v_d.versiune
    AND r.activa AND r.expira_dupa IS NULL AND (r.bucata_id=(v_b->>'id')::bigint OR r.bucata_decl_uid=v_uid);
   IF NOT FOUND THEN RAISE EXCEPTION 'rezervare_pierduta'; END IF;
   IF coalesce(v_d.payload#>>'{confirmare,mod}','') NOT IN ('marcaj','taiata','masurat','marcaj_diferit') THEN
    RAISE EXCEPTION 'lungime_neconfirmata'; END IF;
   IF v_d.payload#>>'{confirmare,mod}'='marcaj' AND (v_d.payload#>>'{confirmare,cm}')::integer
    IS DISTINCT FROM round((v_b->>'lungime_mm')::numeric/10)::integer%100 THEN RAISE EXCEPTION 'marcaj'; END IF;
   v_mm:=public.fn_izo_corectie_mm(v_d.id);
   IF v_mm IS NOT NULL THEN
    IF EXISTS(SELECT 1 FROM public.magazie_bucati b WHERE b.proiect_id=v_d.proiect_id AND b.uid<>v_uid
     AND b.stare NOT IN ('taiata','anulata') AND b.serie_canon=v_b->>'serie_canon' AND b.sarja IS NOT DISTINCT FROM v_b->>'sarja'
     AND b.lungime_cm=round(v_mm::numeric/10)::integer) THEN RAISE EXCEPTION 'r1d'; END IF;
    v_b:=v_b||jsonb_build_object('lungime_mm',v_mm);
   END IF;
   IF v_d.tip='montaj' THEN
    IF (v_d.payload->>'lungime_montata_mm')::integer IS DISTINCT FROM (v_b->>'lungime_mm')::integer THEN RAISE EXCEPTION 'stare'; END IF;
    v_state:=jsonb_set(v_state,ARRAY[v_uid::text],v_b||'{"stare":"montata"}');
   ELSE
    IF v_b->>'executie_teava_id' IS NOT NULL THEN RAISE EXCEPTION 'bucata_in_pachet'; END IF;
    IF v_b->>'stare'='montata' THEN
     SELECT count(*) INTO v_nc FROM jsonb_each(v_caps) x WHERE x.value->>'uid'=v_uid::text AND x.value->>'stare_sudura'='aprobata';
     IF v_nc NOT IN (1,2) THEN RAISE EXCEPTION 'ramura_neacoperita'; END IF;
     IF (SELECT count(*) FROM public.izo_bucati_declarate c WHERE c.declaratie_id=v_d.id AND c.stare='declarata')<>v_nc+1
      OR (SELECT count(*) FROM public.izo_bucati_declarate c WHERE c.declaratie_id=v_d.id AND c.stare='declarata' AND c.destinatie='ramane_montat')<>v_nc
      OR (SELECT count(*) FROM public.izo_bucati_declarate c WHERE c.declaratie_id=v_d.id AND c.stare='declarata' AND c.destinatie='depozit')<>1 THEN RAISE EXCEPTION 'ramura_gresita'; END IF;
    END IF;
    IF v_b->>'tip_cod'<>'teava' THEN RAISE EXCEPTION 'tip_taiere'; END IF;
    IF (v_d.payload->>'baza_mm')::integer IS DISTINCT FROM (v_b->>'lungime_mm')::integer THEN
     RAISE EXCEPTION 'necesita_corectie'; END IF;
    SELECT sum(c.lungime_mm),count(*) INTO v_sum,v_count FROM public.izo_bucati_declarate c
     WHERE c.declaratie_id=v_d.id AND c.declaratie_versiune=v_d.versiune AND c.stare='declarata';
    IF v_count NOT BETWEEN 2 AND 3 OR v_sum IS DISTINCT FROM (v_b->>'lungime_mm')::bigint THEN RAISE EXCEPTION 'r3'; END IF;
    v_state:=jsonb_set(v_state,ARRAY[v_uid::text],v_b||'{"stare":"taiata"}');
    v_prev:=v_b->>'capat_stanga';
    FOR v_c IN SELECT * FROM public.izo_bucati_declarate WHERE declaratie_id=v_d.id AND stare='declarata' ORDER BY cod_bucata LOOP
     IF v_c.declaratie_versiune<>v_d.versiune OR v_c.radacina_id<>v_root OR v_c.capat_stanga IS DISTINCT FROM v_prev
      OR v_c.cod_bucata IS DISTINCT FROM v_c.capat_stanga||v_c.capat_dreapta THEN RAISE EXCEPTION 'geometrie'; END IF;
     v_prev:=v_c.capat_dreapta;
     IF v_c.destinatie NOT IN ('montaj','ramane_montat','depozit') OR v_c.destinatie='ramane_montat' AND v_b->>'stare'<>'montata' THEN RAISE EXCEPTION 'ramura_neacoperita'; END IF;
     IF v_c.destinatie='depozit' AND NOT EXISTS(SELECT 1 FROM public.logistica_depozite dep
      JOIN public.executie_proiecte pr ON pr.site_id=dep.site_id WHERE pr.id=v_d.proiect_id AND dep.activ
       AND dep.id=coalesce(v_c.depozit_destinatie_id,(v_b#>>'{atribute,depozit_origine_id}')::integer)) THEN RAISE EXCEPTION 'depozit_invalid'; END IF;
     IF EXISTS(SELECT 1 FROM public.magazie_bucati b WHERE b.proiect_id=v_d.proiect_id AND b.uid<>v_uid
      AND coalesce(v_state->b.uid::text->>'stare',b.stare) NOT IN ('taiata','anulata')
      AND b.serie_canon=v_b->>'serie_canon' AND b.sarja IS NOT DISTINCT FROM v_b->>'sarja'
      AND b.lungime_cm=round(v_c.lungime_mm::numeric/10)::integer)
      OR EXISTS(SELECT 1 FROM jsonb_each(v_state) x WHERE x.key<>v_uid::text AND x.value->>'stare' NOT IN ('taiata','anulata')
       AND x.value->>'serie_canon'=v_b->>'serie_canon' AND x.value->>'sarja' IS NOT DISTINCT FROM v_b->>'sarja'
       AND round((x.value->>'lungime_mm')::numeric/10)=round(v_c.lungime_mm::numeric/10))
      OR EXISTS(SELECT 1 FROM public.izo_bucati_declarate c JOIN public.magazie_bucati root ON root.id=c.radacina_id
       WHERE c.stare='declarata' AND c.declaratie_id<>v_d.id AND c.uid<>v_uid
        AND root.serie_canon=v_b->>'serie_canon' AND root.sarja IS NOT DISTINCT FROM v_b->>'sarja'
        AND round(c.lungime_mm::numeric/10)=round(v_c.lungime_mm::numeric/10)) THEN RAISE EXCEPTION 'r1d'; END IF;
     v_state:=jsonb_set(v_state,ARRAY[v_c.uid::text],v_b||jsonb_build_object('id',NULL,'uid',v_c.uid,
      'capat_stanga',v_c.capat_stanga,'capat_dreapta',v_c.capat_dreapta,'cod_bucata',v_c.cod_bucata,
      'lungime_mm',v_c.lungime_mm,'stare',CASE WHEN v_c.destinatie='montaj' THEN 'pe_tronson' WHEN v_c.destinatie='ramane_montat' THEN 'montata' ELSE 'in_tranzit' END));
    END LOOP;
    IF v_b->>'stare'='montata' THEN
     FOR v_cap IN SELECT key,value FROM jsonb_each(v_caps) WHERE value->>'uid'=v_uid::text LOOP
      SELECT c.uid INTO v_target FROM public.izo_bucati_declarate c WHERE c.declaratie_id=v_d.id AND c.stare='declarata'
       AND c.destinatie='ramane_montat' AND v_cap.value->>'capat_litera' IN (c.capat_stanga,c.capat_dreapta);
      IF NOT FOUND THEN RAISE EXCEPTION 'ramura_gresita'; END IF;
      v_caps:=jsonb_set(v_caps,ARRAY[v_cap.key],v_cap.value||jsonb_build_object('uid',v_target));
     END LOOP;
     IF EXISTS(SELECT 1 FROM public.izo_bucati_declarate c WHERE c.declaratie_id=v_d.id AND c.stare='declarata'
      AND c.destinatie='ramane_montat' AND NOT EXISTS(SELECT 1 FROM jsonb_each(v_caps) x WHERE x.value->>'uid'=c.uid::text)) THEN RAISE EXCEPTION 'ramura_gresita'; END IF;
     IF EXISTS(SELECT 1 FROM public.izo_bucati_declarate c WHERE c.declaratie_id=v_d.id AND c.stare='declarata'
      AND c.destinatie='ramane_montat' AND NOT EXISTS(SELECT 1 FROM public.izo_rezervari r WHERE r.bucata_decl_uid=c.uid
       AND r.declaratie_id=v_d.id AND r.declaratie_versiune=v_d.versiune AND r.activa AND r.expira_dupa IS NULL)) THEN RAISE EXCEPTION 'rezervare_pierduta'; END IF;
    END IF;
    IF v_prev IS DISTINCT FROM v_b->>'capat_dreapta' THEN RAISE EXCEPTION 'geometrie'; END IF;
   END IF;
   END IF; -- non-coupling
   IF v_s.id IS NOT NULL THEN
    FOR v_cap IN SELECT key,value FROM jsonb_each(v_caps) WHERE (value->>'sudura_id')::bigint=v_s.id LOOP
     v_caps:=jsonb_set(v_caps,ARRAY[v_cap.key],v_cap.value||'{"stare_sudura":"aprobata"}'::jsonb);
    END LOOP;
   END IF;
   v_done:=array_append(v_done,v_d.id); v_order:=array_append(v_order,v_d.id);
   v_left:=array_remove(v_left,v_d.id); v_progress:=true;
  END LOOP;
  IF NOT v_progress THEN RAISE EXCEPTION 'ciclu'; END IF;
 END LOOP;
 RETURN jsonb_build_object('ordine',to_jsonb(v_order),'bucati',v_state,'capete',v_caps);
END $f$;

-- Only exact snapshots enter the existing registry guards, as the real writer.
  CREATE FUNCTION public.fn_izo_taiere_fapt(p_decl bigint) RETURNS bigint
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_d public.izo_declaratii; v_b public.magazie_bucati; v_after public.magazie_bucati;
 v_child public.magazie_bucati; v_c public.izo_bucati_declarate; v_r public.izo_rezervari;
 v_ev public.magazie_bucati_evenimente; v_m public.magazie_bucati_miscari; v_ctx text; v_n bigint; v_expected jsonb;
BEGIN
 IF current_user<>'izo_montaj_writer' THEN RAISE EXCEPTION 'scriitor_invalid'; END IF;
 SELECT * INTO STRICT v_d FROM public.izo_declaratii WHERE id=p_decl;
 SELECT * INTO STRICT v_b FROM public.magazie_bucati WHERE id=v_d.sursa_bucata_id OR uid=v_d.sursa_decl_uid;
 IF v_b.stare NOT IN ('pe_tronson','montata') OR v_b.executie_teava_id IS NOT NULL THEN RAISE EXCEPTION 'stare'; END IF;
 v_after:=v_b; v_after.stare:='taiata'; v_after.server_ver:=nextval('public.izo_server_ver_seq'); v_after.updated_at:=clock_timestamp();
 v_ctx:=concat_ws('|',txid_current()::text,'taiere',p_decl,v_b.proiect_id,v_d.tronson_id,v_after.server_ver,v_b.id);
 PERFORM public.fn_izo_montaj_marcheaza(v_ctx,to_jsonb(v_b),to_jsonb(v_after),NULL);
 UPDATE public.magazie_bucati SET stare=v_after.stare,server_ver=v_after.server_ver,updated_at=v_after.updated_at WHERE id=v_b.id;
 GET DIAGNOSTICS v_n=ROW_COUNT; IF v_n<>1 THEN RAISE EXCEPTION 'bucata_schimbata'; END IF;
 IF to_jsonb(v_after) IS DISTINCT FROM (SELECT to_jsonb(b) FROM public.magazie_bucati b WHERE b.id=v_b.id) THEN RAISE EXCEPTION 'reconciliere_bucata'; END IF;
 v_ev:=jsonb_populate_record(NULL::public.magazie_bucati_evenimente,jsonb_build_object('tip','taiere','proiect_id',v_d.proiect_id,
  'document_tip','izo_declaratie','document_id',p_decl::text,'declarat_de',v_d.declarat_de,'aplicat_de',public.fn_izo_uid(),
  'aplicat_rol','izo_montaj_writer','ora_server',clock_timestamp(),'dispozitiv_id',v_d.dispozitiv_id::text,'server_ver',nextval('public.izo_server_ver_seq')));
 PERFORM public.fn_izo_montaj_marcheaza(v_ctx,NULL,NULL,jsonb_build_object('tabel','magazie_bucati_evenimente','rand',to_jsonb(v_ev)-'id'));
 INSERT INTO public.magazie_bucati_evenimente(tip,proiect_id,document_tip,document_id,declarat_de,aplicat_de,aplicat_rol,ora_server,dispozitiv_id,server_ver)
 VALUES(v_ev.tip,v_ev.proiect_id,v_ev.document_tip,v_ev.document_id,v_ev.declarat_de,v_ev.aplicat_de,v_ev.aplicat_rol,v_ev.ora_server,v_ev.dispozitiv_id,v_ev.server_ver) RETURNING id INTO v_ev.id;
 PERFORM public.fn_izo_taiere_miscare(v_ctx,v_ev.id,'consumat',to_jsonb(v_b),to_jsonb(v_after));
 FOR v_c IN SELECT * FROM public.izo_bucati_declarate WHERE declaratie_id=v_d.id AND stare='declarata' ORDER BY cod_bucata LOOP
  v_child:=v_b; v_child.id:=nextval('public.magazie_bucati_id_seq'); v_child.uid:=v_c.uid; v_child.parinte_id:=v_b.id;
  v_child.cod_bucata:=v_c.cod_bucata; v_child.capat_stanga:=v_c.capat_stanga; v_child.capat_dreapta:=v_c.capat_dreapta;
  v_child.lungime_mm:=v_c.lungime_mm; v_child.lungime_m:=v_c.lungime_mm/1000.0; v_child.lungime_originala_m:=v_child.lungime_m;
  v_child.lungime_calculata:=v_c.lungime_calculata; v_child.lungime_aviz_mm:=NULL; v_child.lungime_masurata_mm:=NULL;
  v_child.aviz_intrare_id:=NULL; v_child.nr_crt_aviz:=NULL; v_child.executie_teava_id:=NULL;
  v_child.server_ver:=nextval('public.izo_server_ver_seq'); v_child.created_at:=now(); v_child.updated_at:=now();
  v_child.stare:=CASE WHEN v_c.destinatie='montaj' THEN 'pe_tronson' WHEN v_c.destinatie='ramane_montat' THEN 'montata' ELSE 'in_tranzit' END;
  -- In transit remains on the tronson; destination is metadata until depot receipt.
  v_child.atribute:=coalesce(v_b.atribute,'{}');
  IF v_c.destinatie='depozit' THEN
   v_child.atribute:=v_child.atribute||jsonb_build_object('destinatie_depozit_id',coalesce(v_c.depozit_destinatie_id,(v_b.atribute->>'depozit_origine_id')::integer));
  END IF;
  v_child.serie_canon:=NULL; v_child.lungime_cm:=NULL;
  v_expected:=to_jsonb(v_child)-ARRAY['serie_canon','lungime_cm'];
  PERFORM public.fn_izo_montaj_marcheaza(v_ctx,NULL,NULL,jsonb_build_object('tabel','magazie_bucati','rand',to_jsonb(v_child)));
  INSERT INTO public.magazie_bucati(proiect_id,comanda_furnizor_id,tip_material_id,serie,sarja,dimensiune,grad_otel,standard,lungime_m,lungime_originala_m,greutate_kg,unghi_curba,cantitate,um,provenienta,izolatie,furnizor,producator,sursa_receptie,fara_packing_list,nr_document,data_receptie,mtc_path,stare,locatie_tip,locatie_site_id,executie_teava_id,atribute,observatii,receptionat_de,receptionat_la,created_by,tip_cod,parinte_id,cod_bucata,capat_stanga,capat_dreapta,dezambiguare,lungime_aviz_mm,lungime_masurata_mm,lungime_mm,lungime_calculata,perete_mm,diametru_mm,lot,aviz_intrare_id,nr_crt_aviz,bend_no,capat_marcaj,depozit_id,tronson_id,id,uid,radacina_id,server_ver,created_at,updated_at) VALUES(v_child.proiect_id,v_child.comanda_furnizor_id,v_child.tip_material_id,v_child.serie,v_child.sarja,v_child.dimensiune,v_child.grad_otel,v_child.standard,v_child.lungime_m,v_child.lungime_originala_m,v_child.greutate_kg,v_child.unghi_curba,v_child.cantitate,v_child.um,v_child.provenienta,v_child.izolatie,v_child.furnizor,v_child.producator,v_child.sursa_receptie,v_child.fara_packing_list,v_child.nr_document,v_child.data_receptie,v_child.mtc_path,v_child.stare,v_child.locatie_tip,v_child.locatie_site_id,v_child.executie_teava_id,v_child.atribute,v_child.observatii,v_child.receptionat_de,v_child.receptionat_la,v_child.created_by,v_child.tip_cod,v_child.parinte_id,v_child.cod_bucata,v_child.capat_stanga,v_child.capat_dreapta,v_child.dezambiguare,v_child.lungime_aviz_mm,v_child.lungime_masurata_mm,v_child.lungime_mm,v_child.lungime_calculata,v_child.perete_mm,v_child.diametru_mm,v_child.lot,v_child.aviz_intrare_id,v_child.nr_crt_aviz,v_child.bend_no,v_child.capat_marcaj,v_child.depozit_id,v_child.tronson_id,v_child.id,v_child.uid,v_child.radacina_id,v_child.server_ver,v_child.created_at,v_child.updated_at);
  SELECT * INTO STRICT v_child FROM public.magazie_bucati WHERE id=v_child.id;
  IF (to_jsonb(v_child)-ARRAY['serie_canon','lungime_cm']) IS DISTINCT FROM v_expected THEN RAISE EXCEPTION 'reconciliere_copil'; END IF;
  PERFORM public.fn_izo_taiere_miscare(v_ctx,v_ev.id,'nascut',NULL,to_jsonb(v_child));
  IF v_c.destinatie='ramane_montat' THEN
   PERFORM public.fn_izo_capete_muta(v_b.id,v_child.id,v_ev.id);
  END IF;
  UPDATE public.izo_bucati_declarate SET stare='aprobata',bucata_id=v_child.id,server_ver=nextval('public.izo_server_ver_seq') WHERE uid=v_c.uid;
  FOR v_r IN SELECT * FROM public.izo_rezervari WHERE bucata_decl_uid=v_c.uid AND activa ORDER BY id LOOP
   IF v_c.destinatie='ramane_montat' AND v_r.declaratie_id=v_d.id THEN
    UPDATE public.izo_rezervari SET activa=false,eliberata_la=clock_timestamp(),motiv_eliberare='consumata',eveniment_id=v_ev.id,
     server_ver=nextval('public.izo_server_ver_seq') WHERE id=v_r.id;
    CONTINUE;
   END IF;
   UPDATE public.izo_rezervari SET activa=false,eliberata_la=clock_timestamp(),motiv_eliberare='transferata',eveniment_id=v_ev.id,
    server_ver=nextval('public.izo_server_ver_seq') WHERE id=v_r.id;
   INSERT INTO public.izo_rezervari(proiect_id,tronson_id,declaratie_id,declaratie_versiune,autor_profile_id,bucata_id,din_depozit,expira_dupa,transfer_din_id)
   VALUES(v_r.proiect_id,v_r.tronson_id,v_r.declaratie_id,v_r.declaratie_versiune,v_r.autor_profile_id,v_child.id,false,v_r.expira_dupa,v_r.id);
  END LOOP;
 END LOOP;
 PERFORM public.fn_izo_montaj_marcheaza(NULL,NULL,NULL,NULL);
 RETURN v_ev.id;
END $f$;

  CREATE FUNCTION public.fn_izo_taiere_miscare(p_ctx text,p_ev bigint,p_rol text,p_before jsonb,p_after jsonb) RETURNS void
 LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, pg_temp AS $f$
DECLARE v_m public.magazie_bucati_miscari;
BEGIN
 v_m:=jsonb_populate_record(NULL::public.magazie_bucati_miscari,jsonb_build_object('eveniment_id',p_ev,
  'proiect_id',p_after->'proiect_id','bucata_id',p_after->'id','rol',p_rol,'stare_inainte',p_before->'stare',
  'stare_dupa',p_after->'stare','din_loc',CASE WHEN p_before IS NOT NULL THEN jsonb_build_object('depozit_id',p_before->'depozit_id','tronson_id',p_before->'tronson_id') END,
  'in_loc',jsonb_build_object('depozit_id',p_after->'depozit_id','tronson_id',p_after->'tronson_id'),
  'lungime_mm',p_after->'lungime_mm','inainte',p_before,'dupa',p_after,'server_ver',nextval('public.izo_server_ver_seq')));
 PERFORM public.fn_izo_montaj_marcheaza(p_ctx,NULL,NULL,jsonb_build_object('tabel','magazie_bucati_miscari','rand',to_jsonb(v_m)-'id'));
 INSERT INTO public.magazie_bucati_miscari(eveniment_id,proiect_id,bucata_id,rol,stare_inainte,stare_dupa,din_loc,in_loc,lungime_mm,inainte,dupa,server_ver)
 VALUES(v_m.eveniment_id,v_m.proiect_id,v_m.bucata_id,v_m.rol,v_m.stare_inainte,v_m.stare_dupa,v_m.din_loc,v_m.in_loc,v_m.lungime_mm,v_m.inainte,v_m.dupa,v_m.server_ver);
END $f$;

-- E4b-2c. Helpers private; topology is simulated before registry DML.
  CREATE FUNCTION public.fn_izo_sudura_decl(p_decl bigint) RETURNS void
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_d public.izo_declaratii; v_s bigint; v_ref jsonb; v_b public.magazie_bucati;
 v_c public.izo_bucati_declarate; v_part text; v_id bigint; v_uid uuid; v_letter text;
BEGIN
 SELECT * INTO STRICT v_d FROM public.izo_declaratii WHERE id=p_decl;
 IF NOT v_d.payload ? 'sudura' THEN
  IF v_d.tip='cuplare' OR coalesce(v_d.payload#>>'{amonte,tip}','inceput_lant')<>'inceput_lant' THEN
   RAISE EXCEPTION 'r4' USING ERRCODE='IZ002'; END IF;
  RETURN;
 END IF;
 IF v_d.tip NOT IN ('montaj','cuplare') OR (v_d.payload#>>'{sudura,nr}')::integer IS NULL
  OR (v_d.payload#>>'{sudura,nr}')::integer<1 OR (coalesce(v_d.payload#>>'{sudura,sufix}','')<>'' AND NOT EXISTS(SELECT 1 FROM public.izo_proiect_config cfg WHERE cfg.proiect_id=v_d.proiect_id AND upper(v_d.payload#>>'{sudura,sufix}')=ANY(cfg.conventie_sufixe))) THEN
  RAISE EXCEPTION 'sudura_cod' USING ERRCODE='IZ001'; END IF;
 INSERT INTO public.izo_suduri(proiect_id,tronson_id,nr,sufix,tip_sudura,declaratie_id,executant,poanson,data_sudura)
 VALUES(v_d.proiect_id,v_d.tronson_id,(v_d.payload#>>'{sudura,nr}')::integer,upper(coalesce(v_d.payload#>>'{sudura,sufix}','')),
  CASE WHEN v_d.tip='cuplare' THEN 'cuplare' ELSE 'linie' END,v_d.id,v_d.payload->>'executant',v_d.payload->>'poanson',v_d.data_montaj)
 RETURNING id INTO v_s;
 FOREACH v_part IN ARRAY ARRAY['amonte','aval'] LOOP
  v_ref:=CASE WHEN v_d.tip='cuplare' THEN v_d.payload->CASE WHEN v_part='amonte' THEN 'capat1' ELSE 'capat2' END
   WHEN v_part='amonte' THEN v_d.payload->'amonte'
   ELSE jsonb_build_object('bucata_id',v_d.bucata_id,'decl_uid',v_d.bucata_decl_uid,'capat',v_d.payload->>'capat_amonte') END;
  v_id:=(v_ref->>'bucata_id')::bigint; v_uid:=(v_ref->>'decl_uid')::uuid; v_letter:=v_ref->>'capat';
  IF num_nonnulls(v_id,v_uid)<>1 OR v_letter IS NULL THEN RAISE EXCEPTION 'r4' USING ERRCODE='IZ002'; END IF;
  IF v_uid IS NOT NULL THEN
   SELECT * INTO v_c FROM public.izo_bucati_declarate WHERE uid=v_uid;
   IF NOT FOUND OR v_c.stare='anulata' OR NOT EXISTS(SELECT 1 FROM public.izo_declaratii d WHERE d.id=v_c.declaratie_id
    AND d.declarat_de=v_d.declarat_de AND d.proiect_id=v_d.proiect_id AND d.tronson_id=v_d.tronson_id
    AND d.uid=v_d.depinde_de_uid AND d.versiune=v_d.depinde_de_versiune) THEN RAISE EXCEPTION 'dependenta' USING ERRCODE='IZ003'; END IF;
   IF v_letter NOT IN (v_c.capat_stanga,v_c.capat_dreapta) THEN RAISE EXCEPTION 'r4' USING ERRCODE='IZ002'; END IF;
   SELECT id INTO v_id FROM public.magazie_bucati WHERE uid=v_uid;
   IF v_id IS NOT NULL THEN v_uid:=NULL; END IF;
  END IF;
  IF v_id IS NOT NULL THEN
   SELECT * INTO v_b FROM public.magazie_bucati WHERE id=v_id;
   IF NOT FOUND OR v_b.proiect_id<>v_d.proiect_id OR v_b.tronson_id IS DISTINCT FROM v_d.tronson_id
    OR v_b.stare NOT IN ('pe_tronson','montata') OR v_letter NOT IN (v_b.capat_stanga,v_b.capat_dreapta) THEN
    RAISE EXCEPTION 'r4' USING ERRCODE='IZ002'; END IF;
  END IF;
  INSERT INTO public.izo_suduri_capete(sudura_id,parte,bucata_id,bucata_decl_uid,capat_litera)
  VALUES(v_s,v_part,v_id,v_uid,v_letter);
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.izo_suduri_capete a JOIN public.izo_suduri_capete b ON b.sudura_id=a.sudura_id AND b.parte<>a.parte
  WHERE a.sudura_id=v_s AND (a.bucata_id=b.bucata_id OR a.bucata_decl_uid=b.bucata_decl_uid)) THEN
  RAISE EXCEPTION 'r4' USING ERRCODE='IZ002'; END IF;
END $f$;

-- Declaration-time checks use committed outer endpoints. Approval repeats them
-- on the virtual graph, including earlier cuts in the selected lot.
  CREATE FUNCTION public.fn_izo_taiere_ramura(p_decl bigint) RETURNS void
 LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_d public.izo_declaratii; v_b public.magazie_bucati; v_n integer;
BEGIN
 SELECT * INTO STRICT v_d FROM public.izo_declaratii WHERE id=p_decl;
 IF v_d.tip<>'taiere' THEN RETURN; END IF;
 SELECT * INTO v_b FROM public.magazie_bucati WHERE id=v_d.sursa_bucata_id OR uid=v_d.sursa_decl_uid;
 IF v_b.id IS NULL THEN RETURN; END IF;
 IF v_b.executie_teava_id IS NOT NULL THEN RAISE EXCEPTION 'bucata_in_pachet' USING ERRCODE='IZ002'; END IF;
 IF v_b.stare<>'montata' THEN
  IF EXISTS(SELECT 1 FROM public.izo_bucati_declarate c WHERE c.declaratie_id=p_decl AND c.stare='declarata' AND c.destinatie='ramane_montat') THEN
   RAISE EXCEPTION 'ramura_gresita' USING ERRCODE='IZ002'; END IF;
  RETURN;
 END IF;
 SELECT count(*) INTO v_n FROM public.izo_suduri_capete c JOIN public.izo_suduri w ON w.id=c.sudura_id
 WHERE c.bucata_id=v_b.id AND c.activ AND w.stare='aprobata';
 IF v_n NOT IN (1,2) THEN RAISE EXCEPTION 'ramura_neacoperita' USING ERRCODE='IZ002'; END IF;
 IF (SELECT count(*) FROM public.izo_bucati_declarate c WHERE c.declaratie_id=p_decl AND c.stare='declarata')<>v_n+1
  OR (SELECT count(*) FROM public.izo_bucati_declarate c WHERE c.declaratie_id=p_decl AND c.stare='declarata' AND c.destinatie='ramane_montat')<>v_n
  OR (SELECT count(*) FROM public.izo_bucati_declarate c WHERE c.declaratie_id=p_decl AND c.stare='declarata' AND c.destinatie='depozit')<>1
  OR EXISTS(SELECT 1 FROM public.izo_suduri_capete e JOIN public.izo_suduri w ON w.id=e.sudura_id
   WHERE e.bucata_id=v_b.id AND e.activ AND w.stare='aprobata' AND NOT EXISTS(SELECT 1 FROM public.izo_bucati_declarate c
    WHERE c.declaratie_id=p_decl AND c.stare='declarata' AND c.destinatie='ramane_montat' AND e.capat_litera IN (c.capat_stanga,c.capat_dreapta)))
 THEN RAISE EXCEPTION 'ramura_gresita' USING ERRCODE='IZ002'; END IF;
END $f$;

  CREATE FUNCTION public.fn_izo_sudura_aproba(p_decl bigint) RETURNS void
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_s public.izo_suduri; v_n bigint;
BEGIN
 SELECT * INTO v_s FROM public.izo_suduri WHERE declaratie_id=p_decl AND stare='declarata';
 IF NOT FOUND THEN RETURN; END IF;
 UPDATE public.izo_suduri_capete c SET bucata_id=b.id,bucata_decl_uid=NULL,server_ver=nextval('public.izo_server_ver_seq')
 FROM public.magazie_bucati b WHERE c.sudura_id=v_s.id AND c.activ AND b.uid=c.bucata_decl_uid;
 SELECT count(*) INTO v_n FROM public.izo_suduri_capete c JOIN public.magazie_bucati b ON b.id=c.bucata_id
 WHERE c.sudura_id=v_s.id AND c.activ AND b.stare='montata' AND b.tronson_id=v_s.tronson_id
 AND c.capat_litera IN (b.capat_stanga,b.capat_dreapta);
 IF v_n<>2 THEN RAISE EXCEPTION 'r4'; END IF;
 UPDATE public.izo_suduri SET stare='aprobata',tranzitie_perete=(SELECT count(DISTINCT b.perete_mm)>1
  FROM public.izo_suduri_capete c JOIN public.magazie_bucati b ON b.id=c.bucata_id WHERE c.sudura_id=v_s.id AND c.activ),
  server_ver=nextval('public.izo_server_ver_seq') WHERE id=v_s.id;
END $f$;

  CREATE FUNCTION public.fn_izo_capete_muta(p_sursa bigint,p_copil bigint,p_ev bigint) RETURNS void
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_c public.magazie_bucati; v_e public.izo_suduri_capete;
BEGIN
 SELECT * INTO STRICT v_c FROM public.magazie_bucati WHERE id=p_copil;
 FOR v_e IN SELECT * FROM public.izo_suduri_capete WHERE bucata_id=p_sursa AND activ
  AND capat_litera IN (v_c.capat_stanga,v_c.capat_dreapta) ORDER BY id LOOP
  UPDATE public.izo_suduri_capete SET activ=false,server_ver=nextval('public.izo_server_ver_seq') WHERE id=v_e.id;
  INSERT INTO public.izo_suduri_capete(sudura_id,parte,bucata_id,capat_litera,de_la_eveniment_id)
  VALUES(v_e.sudura_id,v_e.parte,p_copil,v_e.capat_litera,p_ev);
 END LOOP;
END $f$;

  CREATE FUNCTION public.fn_izo_corectie_mm(p_decl bigint) RETURNS integer
 LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_d public.izo_declaratii; v_b public.magazie_bucati; v_mm integer; v_tol integer;
BEGIN
 SELECT * INTO STRICT v_d FROM public.izo_declaratii WHERE id=p_decl;
 IF v_d.tip='cuplare' THEN RETURN NULL; END IF;
 SELECT * INTO v_b FROM public.magazie_bucati WHERE id=coalesce(v_d.sursa_bucata_id,v_d.bucata_id)
  OR uid=coalesce(v_d.sursa_decl_uid,v_d.bucata_decl_uid);
 v_mm:=CASE WHEN v_d.tip='taiere' THEN (v_d.payload->>'baza_mm')::integer
  ELSE coalesce((v_d.payload#>>'{confirmare,masurata_mm}')::integer,(v_d.payload->>'lungime_masurata_mm')::integer) END;
 SELECT toleranta_mm INTO v_tol FROM public.izo_proiect_config WHERE proiect_id=v_d.proiect_id;
 IF v_mm IS NULL OR v_mm=v_b.lungime_mm THEN RETURN NULL; END IF;
 IF v_d.payload#>>'{confirmare,mod}' NOT IN ('marcaj_diferit','masurat') THEN RETURN NULL; END IF;
 IF v_d.payload#>>'{confirmare,mod}'='masurat' AND abs(v_mm-v_b.lungime_mm)<=v_tol THEN RETURN NULL; END IF;
 IF v_mm NOT BETWEEN 1 AND 30000 OR v_b.id IS NULL OR v_b.parinte_id IS NOT NULL
  OR EXISTS(SELECT 1 FROM public.magazie_bucati b WHERE b.parinte_id=v_b.id)
  OR EXISTS(SELECT 1 FROM public.izo_bucati_declarate c WHERE c.radacina_id=v_b.id AND c.declaratie_id<>v_d.id AND c.stare<>'anulata') THEN
  RAISE EXCEPTION 'corectie_in_arbore'; END IF;
 RETURN v_mm;
END $f$;

  CREATE FUNCTION public.fn_izo_corectie_fapt(p_bucata bigint,p_ref text,p_tronson bigint,p_autor uuid,p_dispozitiv text,p_motiv text,p_mm integer) RETURNS bigint
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_b public.magazie_bucati; v_dupa public.magazie_bucati; v_ev public.magazie_bucati_evenimente;
 v_m public.magazie_bucati_miscari; v_ctx text; v_n bigint; v_now timestamptz:=clock_timestamp();
BEGIN
 IF current_user<>'izo_montaj_writer' OR p_mm NOT BETWEEN 1 AND 30000 OR length(btrim(coalesce(p_motiv,'')))<3 THEN RAISE EXCEPTION 'scriitor_invalid' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT v_b FROM public.magazie_bucati WHERE id=p_bucata FOR UPDATE;
 v_dupa:=v_b; v_dupa.updated_at:=v_now; v_dupa.server_ver:=nextval('public.izo_server_ver_seq');
 IF v_b.parinte_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.magazie_bucati b WHERE b.parinte_id=v_b.id)
  OR EXISTS(SELECT 1 FROM public.izo_bucati_declarate c WHERE c.radacina_id=v_b.id AND c.declaratie_id<>p_ref::bigint AND c.stare<>'anulata') THEN RAISE EXCEPTION 'corectie_in_arbore'; END IF;
 v_dupa.lungime_mm:=p_mm; v_dupa.lungime_masurata_mm:=p_mm; v_dupa.lungime_m:=p_mm/1000.0;
 v_dupa.lungime_originala_m:=p_mm/1000.0; v_dupa.lungime_cm:=round(p_mm::numeric/10)::integer;
 v_ctx:=concat_ws('|',txid_current()::text,'corectie',p_ref,v_b.proiect_id,p_tronson,v_dupa.server_ver,v_b.id);
 PERFORM public.fn_izo_montaj_marcheaza(v_ctx,to_jsonb(v_b),to_jsonb(v_dupa),NULL);
 UPDATE public.magazie_bucati SET lungime_mm=v_dupa.lungime_mm,lungime_masurata_mm=v_dupa.lungime_masurata_mm,
  lungime_m=v_dupa.lungime_m,lungime_originala_m=v_dupa.lungime_originala_m,server_ver=v_dupa.server_ver,updated_at=v_now WHERE id=v_b.id;
 GET DIAGNOSTICS v_n=ROW_COUNT;
 IF v_n<>1 THEN RAISE EXCEPTION 'bucata_schimbata'; END IF;
 IF to_jsonb(v_dupa) IS DISTINCT FROM (SELECT to_jsonb(b) FROM public.magazie_bucati b WHERE b.id=v_b.id) THEN RAISE EXCEPTION 'reconciliere_bucata'; END IF;
 v_ev:=jsonb_populate_record(NULL::public.magazie_bucati_evenimente,jsonb_build_object(
  'tip','corectie','proiect_id',v_b.proiect_id,
  'document_tip','izo_declaratie','document_id',p_ref,
  'motiv',p_motiv,'declarat_de',p_autor,'aplicat_de',public.fn_izo_uid(),'aplicat_rol','izo_montaj_writer',
  'ora_server',v_now,'ora_tableta',NULL,'dispozitiv_id',p_dispozitiv,'server_ver',nextval('public.izo_server_ver_seq')));
 PERFORM public.fn_izo_montaj_marcheaza(v_ctx,NULL,NULL,jsonb_build_object('tabel','magazie_bucati_evenimente','rand',to_jsonb(v_ev)-'id'));
 INSERT INTO public.magazie_bucati_evenimente(tip,proiect_id,document_tip,document_id,import_id,storno_de_eveniment_id,motiv,
  declarat_de,aplicat_de,aplicat_rol,ora_server,ora_tableta,dispozitiv_id,server_ver)
 VALUES(v_ev.tip,v_ev.proiect_id,v_ev.document_tip,v_ev.document_id,v_ev.import_id,v_ev.storno_de_eveniment_id,v_ev.motiv,
  v_ev.declarat_de,v_ev.aplicat_de,v_ev.aplicat_rol,v_ev.ora_server,v_ev.ora_tableta,v_ev.dispozitiv_id,v_ev.server_ver) RETURNING id INTO v_ev.id;
 v_m:=jsonb_populate_record(NULL::public.magazie_bucati_miscari,jsonb_build_object('eveniment_id',v_ev.id,'proiect_id',v_b.proiect_id,
  'bucata_id',v_b.id,'rol','corectat','stare_inainte',v_b.stare,'stare_dupa',v_dupa.stare,
  'din_loc',jsonb_build_object('depozit_id',v_b.depozit_id,'tronson_id',v_b.tronson_id),
  'in_loc',jsonb_build_object('depozit_id',v_dupa.depozit_id,'tronson_id',v_dupa.tronson_id),
  'lungime_mm',v_dupa.lungime_mm,'inainte',to_jsonb(v_b),'dupa',to_jsonb(v_dupa),'server_ver',nextval('public.izo_server_ver_seq')));
 PERFORM public.fn_izo_montaj_marcheaza(v_ctx,NULL,NULL,jsonb_build_object('tabel','magazie_bucati_miscari','rand',to_jsonb(v_m)-'id'));
 INSERT INTO public.magazie_bucati_miscari(eveniment_id,proiect_id,bucata_id,rol,stare_inainte,stare_dupa,din_loc,in_loc,lungime_mm,inainte,dupa,server_ver)
 VALUES(v_m.eveniment_id,v_m.proiect_id,v_m.bucata_id,v_m.rol,v_m.stare_inainte,v_m.stare_dupa,v_m.din_loc,v_m.in_loc,
  v_m.lungime_mm,v_m.inainte,v_m.dupa,v_m.server_ver);
 PERFORM public.fn_izo_montaj_marcheaza(NULL,NULL,NULL,NULL);
 RETURN v_ev.id;
END $f$;

   CREATE OR REPLACE FUNCTION public.fn_izo_garda_montaj(p_tabel text,p_op text,p_inainte jsonb,p_dupa jsonb)
    RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, pg_temp AS $f$
  DECLARE v_ctx text:=current_setting('izo.montaj_ctx',true); v_pachet bigint; v_op text; v_dupa_comparabil jsonb;
  BEGIN
    IF current_user='izo_montaj_writer' AND split_part(v_ctx,'|',1)=txid_current()::text
     AND split_part(v_ctx,'|',2)='corectie' AND p_tabel='magazie_bucati' AND p_op='UPDATE'
     AND p_inainte=nullif(current_setting('izo.montaj_bucata_inainte',true),'')::jsonb
     AND (p_dupa-ARRAY['serie_canon','lungime_cm'])=(nullif(current_setting('izo.montaj_bucata_dupa',true),'')::jsonb-ARRAY['serie_canon','lungime_cm'])
     AND split_part(v_ctx,'|',7)=p_inainte->>'id' AND split_part(v_ctx,'|',4)=p_inainte->>'proiect_id'
     AND split_part(v_ctx,'|',6)=p_dupa->>'server_ver'
     AND (p_inainte-ARRAY['lungime_mm','lungime_masurata_mm','lungime_m','lungime_originala_m','server_ver','updated_at','serie_canon','lungime_cm'])
      =(p_dupa-ARRAY['lungime_mm','lungime_masurata_mm','lungime_m','lungime_originala_m','server_ver','updated_at','serie_canon','lungime_cm'])
     THEN RETURN true; END IF;
    -- E4b-2: private writer supplies the exact typed image immediately before DML.
    -- Generated STORED values are absent in BEFORE NEW, even on an unrelated UPDATE.
    IF current_user='izo_montaj_writer'
      AND split_part(v_ctx,'|',1)=txid_current()::text
      AND split_part(v_ctx,'|',2) IN ('aproba','iesire','taiere')
      AND p_op='UPDATE' AND p_tabel='magazie_bucati'
      AND p_inainte IS NOT NULL AND p_dupa IS NOT NULL
      AND p_dupa->'serie_canon'='null'::jsonb AND p_dupa->'lungime_cm'='null'::jsonb
      AND p_inainte=nullif(current_setting('izo.montaj_bucata_inainte',true),'')::jsonb
      AND (p_dupa || jsonb_build_object('serie_canon',p_inainte->'serie_canon','lungime_cm',p_inainte->'lungime_cm'))
        =nullif(current_setting('izo.montaj_bucata_dupa',true),'')::jsonb
      AND split_part(v_ctx,'|',4)=p_inainte->>'proiect_id'
      AND split_part(v_ctx,'|',6)=p_dupa->>'server_ver'
      AND split_part(v_ctx,'|',7)=p_inainte->>'id'
      AND (p_inainte-ARRAY['stare','locatie_tip','depozit_id','tronson_id','atribute','server_ver','updated_at'])
        =((p_dupa || jsonb_build_object('serie_canon',p_inainte->'serie_canon','lungime_cm',p_inainte->'lungime_cm'))
          -ARRAY['stare','locatie_tip','depozit_id','tronson_id','atribute','server_ver','updated_at'])
      AND ((split_part(v_ctx,'|',2)='aproba' AND p_inainte->>'stare'='pe_tronson' AND p_dupa->>'stare'='montata'
        AND (p_inainte-ARRAY['stare','server_ver','updated_at'])=
          ((p_dupa || jsonb_build_object('serie_canon',p_inainte->'serie_canon','lungime_cm',p_inainte->'lungime_cm'))-ARRAY['stare','server_ver','updated_at']))
        OR (split_part(v_ctx,'|',2)='taiere' AND p_inainte->>'stare' IN ('pe_tronson','montata') AND p_dupa->>'stare'='taiata'
          AND (p_inainte-ARRAY['stare','server_ver','updated_at'])=
           ((p_dupa || jsonb_build_object('serie_canon',p_inainte->'serie_canon','lungime_cm',p_inainte->'lungime_cm'))-ARRAY['stare','server_ver','updated_at']))
        OR (split_part(v_ctx,'|',2)='iesire' AND p_inainte->>'stare' IN ('sosit','receptionat','retur')
          AND p_dupa->>'stare'='pe_tronson' AND p_dupa->>'locatie_tip'='tronson'
          AND p_dupa->>'depozit_id' IS NULL AND p_dupa->>'tronson_id'=split_part(v_ctx,'|',5)))
      THEN RETURN true; END IF;
    IF current_user='izo_montaj_writer' AND split_part(v_ctx,'|',1)=txid_current()::text
      AND split_part(v_ctx,'|',2) IN ('aproba','iesire','taiere','corectie') AND p_op='INSERT'
      AND p_tabel IN ('magazie_bucati_evenimente','magazie_bucati_miscari')
      AND p_inainte IS NULL AND p_dupa IS NOT NULL
      AND split_part(v_ctx,'|',4)=p_dupa->>'proiect_id'
      AND (nullif(current_setting('izo.montaj_rand_asteptat',true),'')::jsonb)
        =jsonb_build_object('tabel',p_tabel,'rand',p_dupa-'id') THEN RETURN true; END IF;
    IF current_user='izo_montaj_writer' AND split_part(v_ctx,'|',1)=txid_current()::text
      AND split_part(v_ctx,'|',2)='taiere' AND p_op='INSERT' AND p_tabel='magazie_bucati'
      AND p_inainte IS NULL AND p_dupa->'serie_canon'='null'::jsonb AND p_dupa->'lungime_cm'='null'::jsonb
      AND split_part(v_ctx,'|',4)=p_dupa->>'proiect_id'
      AND split_part(v_ctx,'|',7)=p_dupa->>'parinte_id'
      AND nullif(current_setting('izo.montaj_rand_asteptat',true),'')::jsonb
        =jsonb_build_object('tabel',p_tabel,'rand',p_dupa) THEN RETURN true; END IF;
    -- E4a writes only the link. No events/movements/imports/config authorization yet.
    IF current_user='izo_montaj_writer' AND p_tabel='magazie_bucati' AND p_op='UPDATE'
      AND p_inainte IS NOT NULL AND p_dupa IS NOT NULL
      -- PG16 computes STORED generated columns AFTER BEFORE triggers: NEW has NULL.
      -- Require that exact trigger shape; restore only these two derived values for
      -- comparison with the stored snapshot. Their sources (serie/lungime_mm) stay immutable.
      AND p_dupa->'serie_canon' = 'null'::jsonb AND p_dupa->'lungime_cm' = 'null'::jsonb THEN
      v_dupa_comparabil:=p_dupa || jsonb_build_object(
        'serie_canon',p_inainte->'serie_canon','lungime_cm',p_inainte->'lungime_cm');
      v_op:=CASE WHEN p_dupa->>'executie_teava_id' IS NULL THEN 'dezleaga' ELSE 'leaga' END;
      SELECT pachet_id INTO v_pachet FROM public.executie_tevi
        WHERE id=coalesce((p_dupa->>'executie_teava_id')::bigint,(p_inainte->>'executie_teava_id')::bigint);
      IF v_ctx = concat_ws('|',txid_current()::text,v_op,v_pachet::text,
          p_inainte->>'proiect_id',p_inainte->>'tronson_id',p_dupa->>'server_ver',p_inainte->>'id')
        AND v_pachet IS NOT NULL AND p_inainte->>'tip_cod' IN ('teava','curba')
        AND p_inainte->>'stare'='montata'
        AND ((v_op='leaga' AND p_inainte->>'executie_teava_id' IS NULL)
          OR (v_op='dezleaga' AND p_inainte->>'executie_teava_id' IS NOT NULL))
        AND nullif(current_setting('izo.montaj_bucata_inainte',true),'')::jsonb=p_inainte
        AND nullif(current_setting('izo.montaj_bucata_dupa',true),'')::jsonb=v_dupa_comparabil
        AND (p_inainte-ARRAY['executie_teava_id','server_ver','updated_at'])=
            (v_dupa_comparabil-ARRAY['executie_teava_id','server_ver','updated_at']) THEN RETURN true; END IF;
    END IF;
    RAISE EXCEPTION 'E4a context montaj invalid pe %',p_tabel USING ERRCODE='42501';
  END $f$;
   CREATE OR REPLACE FUNCTION public.fn_izo_flux_admin(p_tronson bigint,p_activ boolean,p_motiv text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
  DECLARE v_pr bigint; v_c public.izo_tronson_config; v_lipsa text[];
  BEGIN
    IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'E4a READ COMMITTED' USING ERRCODE='25001'; END IF;
    PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
    IF session_user<>'postgres' THEN RAISE EXCEPTION 'E4a numai sesiune postgres' USING ERRCODE='42501'; END IF;
    IF coalesce(current_setting('izo.montaj_ctx',true),'')<>'' OR coalesce(current_setting('izo.receptie_ctx',true),'')<>''
      OR coalesce(current_setting('izo.registru_tx',true),'')<>'' THEN RAISE EXCEPTION 'E4a context ocupat'; END IF;
    IF p_activ IS NULL OR length(btrim(coalesce(p_motiv,'')))<3 THEN RAISE EXCEPTION 'E4a parametri flux'; END IF;
    IF p_activ THEN
      v_lipsa:=public.fn_izo_porti_lipsa();
      IF cardinality(v_lipsa)<>0 THEN RAISE EXCEPTION 'E4a porti: %',v_lipsa; END IF;
    END IF;
    LOCK TABLE public.izo_tronson_config,public.executie_tronsoane,public.executie_pachete_lansare,
      public.executie_tevi,public.magazie_bucati,public.magazie_bucati_evenimente IN ACCESS SHARE MODE;
    SELECT proiect_id INTO v_pr FROM public.executie_tronsoane WHERE id=p_tronson;
    IF v_pr IS NULL THEN RAISE EXCEPTION 'E4a tronson lipsa'; END IF;
    PERFORM public.fn_izo_lock_proiect(v_pr,true);
    SELECT * INTO v_c FROM public.izo_tronson_config WHERE tronson_id=p_tronson FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'config_lipsa'; END IF;
    IF v_c.proiect_id<>v_pr THEN RAISE EXCEPTION 'E4a proiect diferit'; END IF;
    IF p_activ THEN
      IF coalesce(public.fn_izo_nivel(v_pr),'off')='off' THEN RAISE EXCEPTION 'E4a nivel off'; END IF;
      -- E4a-1 cannot verify a legare without E4b suduri: fail closed on that row type.
      IF EXISTS(SELECT 1 FROM public.executie_tevi t JOIN public.executie_pachete_lansare p ON p.id=t.pachet_id
        WHERE p.tronson_id=p_tronson AND (coalesce(to_jsonb(t)->>'tip_rand','teava') NOT IN ('teava','curba')
          OR (SELECT count(*) FROM public.magazie_bucati b WHERE b.executie_teava_id=t.id AND b.stare='montata'
            AND b.tronson_id=p_tronson AND b.proiect_id=v_pr
            AND b.tip_cod=coalesce(to_jsonb(t)->>'tip_rand','teava'))<>1))
        THEN RAISE EXCEPTION 'E4a randuri nelegate'; END IF;
      IF EXISTS(SELECT 1 FROM public.executie_pachete_lansare p WHERE p.tronson_id=p_tronson
        AND (to_jsonb(p)->>'aprobat_la' IS NOT NULL OR to_jsonb(p)->>'pdf_aprobare_path' IS NOT NULL
          OR to_jsonb(p)->>'status' IN ('aprobat','lansat','finalizat'))) THEN RAISE EXCEPTION 'E4a antet aprobat'; END IF;
    ELSE
      IF EXISTS(SELECT 1 FROM public.magazie_bucati WHERE tronson_id=p_tronson AND stare IN ('montata','taiata'))
        OR EXISTS(SELECT 1 FROM public.magazie_bucati_miscari m JOIN public.magazie_bucati_evenimente e ON e.id=m.eveniment_id
          WHERE e.proiect_id=v_pr AND e.tip IN ('montaj','taiere') AND
            (m.inainte->>'tronson_id'=p_tronson::text OR m.dupa->>'tronson_id'=p_tronson::text
             OR m.din_loc->>'tronson_id'=p_tronson::text OR m.in_loc->>'tronson_id'=p_tronson::text))
        THEN RAISE EXCEPTION 'E4a fapte montaj; oprire refuzata'; END IF;
      -- Later E4b must replace this entry with checks on declarations/reservations/fronts.
      IF EXISTS(SELECT 1 FROM public.izo_declaratii WHERE tronson_id=p_tronson AND stare NOT IN ('aprobata','respinsa','stearsa'))
        OR EXISTS(SELECT 1 FROM public.izo_rezervari WHERE tronson_id=p_tronson AND activa)
        OR EXISTS(SELECT 1 FROM public.izo_fronturi WHERE tronson_id=p_tronson AND activ)
        THEN RAISE EXCEPTION 'E4b front/declaratii/rezervari; oprire refuzata'; END IF;
    END IF;
    PERFORM set_config('izo.montaj_ctx',txid_current()::text || '|flux|' || p_tronson,true);
    UPDATE public.izo_tronson_config SET flux_montaj=p_activ,flux_de_la=clock_timestamp(),flux_motiv=btrim(p_motiv),
      flux_schimbat_de=session_user,server_ver=nextval('public.izo_server_ver_seq') WHERE tronson_id=p_tronson;
    PERFORM set_config('izo.montaj_ctx','',true);
    RETURN p_activ;
  END $f$;
   CREATE OR REPLACE FUNCTION public.fn_izo_porti_e4_lipsa() RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$
  DECLARE v_lipsa text[]:='{}';
  BEGIN
    IF public.fn_izo_porti_e4_definitii() IS DISTINCT FROM substring(obj_description('public.fn_izo_porti_e4_definitii()'::regprocedure,'pg_proc') FROM '^porti_e4=([0-9a-f]{32})$') THEN
      v_lipsa:=array_append(v_lipsa,'E4 definitii diferite'); END IF;
    IF has_schema_privilege('izo_montaj_writer','public','CREATE') OR EXISTS
      (SELECT 1 FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relkind='S'
       AND has_sequence_privilege('izo_montaj_writer',c.oid,'USAGE') IS DISTINCT FROM (c.oid IN ('public.izo_server_ver_seq'::regclass,'public.magazie_bucati_evenimente_id_seq'::regclass,'public.magazie_bucati_miscari_id_seq'::regclass,'public.magazie_bucati_id_seq'::regclass,'public.izo_rezervari_id_seq'::regclass)))
      THEN v_lipsa:=array_append(v_lipsa,'E4 ACL schema/secvente'); END IF;
    IF EXISTS(SELECT 1 FROM pg_trigger g WHERE g.tgname LIKE 'a0_izo_flux_%' AND g.tgenabled<>'A') THEN v_lipsa:=array_append(v_lipsa,'E4 trigger dezactivat'); END IF;
    IF EXISTS(SELECT 1 FROM pg_trigger g JOIN pg_trigger e ON e.tgrelid=g.tgrelid
      WHERE e.tgname IN ('a0_izo_flux_tevi','a0_izo_flux_pachete','a0_izo_flux_documente')
        AND NOT g.tgisinternal AND (g.tgtype::integer & 2)=2 AND g.tgname<e.tgname) THEN v_lipsa:=array_append(v_lipsa,'E4 ordinea BEFORE'); END IF;
    RETURN v_lipsa;
  END $f$;
   CREATE OR REPLACE FUNCTION public.fn_izo_depozit_in_registru(p_depozit integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$
    SELECT EXISTS (SELECT 1 FROM public.magazie_bucati b WHERE b.tip_cod IS NOT NULL
                    AND (b.depozit_id = p_depozit OR b.atribute->>'depozit_origine_id' = p_depozit::text OR b.atribute->>'destinatie_depozit_id' = p_depozit::text))
  $f$;
